const upanishads = [
    {
        id: "isha",
        title: "Isha Upanishad (ஈவாஸ்யோபனிஷத்)",
        subtitle: "The Divinity in All (Full 18 Verses)",
        shanti_mantra: {
            sanskrit: "ॐ पूर्णमदः पूर्णमिदं पूर्णात् पूर्णमुदच्यते ।\nपूर्णस्य पूर्णमादाय पूर्णमेवावशिष्यते ॥\nॐ शान्तिः शान्तिः शान्तिः ॥",
            tamil_trans: "ஓம் பூர்ணமத: பூர்ணமிதம் பூர்ணாத் பூர்ணமுதச்யதே |\nபூர்ணஸ்ய பூர்ணமாதாய பூர்ணமேவாவசிஷ்யதே ||\nஓம் சாந்தி: சாந்தி: சாந்தி: ||",
            english: "Om. That is full; this is full. From fullness, fullness comes out. Taking fullness from fullness, fullness indeed remains. Om Peace, Peace, Peace."
        },
        verses: [
            { id: 1, sanskrit: "ईशा वास्यमिदँ सर्वं यत्किञ्च जगत्यां जगत् ।\nतेन त्यक्तेन भुञ्जीथा मा गृधः कस्यस्विद्धनम् ॥ १॥", tamil_trans: "ஈஷா வாஸ்யமிதம் ஸர்வம் யத்கிஞ்ச ஜகத் யாம் ஜகத் |\nதேன த்யக்தேன புஞ்ஜீதா மா க்ருத: கஸ்யஸ்வித் தனம் || 1 ||", english: "All this - whatever exists in this changing universe - should be covered by the Lord. Enjoy through renunciation. Do not covet anyone's wealth.", commentary_tamil: "உலகம் இறைவனால் வியாபிக்கப்பட வேண்டும். பற்றற்ற நிலையில் வாழ்வதே உண்மையான இன்பம்.", commentary_english: "Perceive the Divine in everything. Enjoy life by renouncing attachment." },
            { id: 2, sanskrit: "कुर्वन्नेवेह कर्माणि जिजीविषेच्छतँ समाः ।\nएवं त्वयि नान्यथेतोऽस्ति न कर्म लिप्यते नरे ॥ २॥", tamil_trans: "குர்வன்நேவேஹ கர்மாணி ஜிஜீவிஷேச்சதம் ஸமா: |\nஏவம் த்வயி நான்யதேதோ'ஸ்தி ந கர்ம லிப்யதே நரே || 2 ||", english: "One should desire to live a hundred years performing duties here. Thus, and in no other way, work will not cling to you.", commentary_tamil: "பலனை எதிர்பார்க்காமல் கடமையைச் செய்பவனை கர்மவினை பற்றுவதில்லை.", commentary_english: "Karma Yoga: Action without attachment to results leads to freedom." },
            { id: 3, sanskrit: "असुर्या नाम ते लोका अन्धेन तमसाऽऽवृताः ।\nताँस्ते प्रेत्याभिगच्छन्ति ये के चात्महनो जनाः ॥ ३॥", tamil_trans: "அஸுர்யா நாம தே லோகா அந்தேன தமஸா'வ்ருதா: |\nதாம்ஸ்தே ப்ரேத்யாபிகச்சந்தி யே கே சாத்மஹனோ ஜனா: || 3 ||", english: "Sunless are those worlds, covered by blinding darkness. To them go those who kill the Self (ignore the Atman) after death.", commentary_tamil: "ஆத்மாவை அறியாதவர்கள் இருண்ட உலகத்தை அடைகிறார்கள்.", commentary_english: "Ignorance of the Self is spiritual suicide." },
            { id: 4, sanskrit: "अनेजदेकं मनसो जवीयो नैनद्देवा आप्नुवन्पूर्वमर्षत् ।\nतद्धावतोऽन्यान् अत्येति तिष्ठत् तस्मिन्नपो मातरिश्वा दधाति ॥ ४॥", tamil_trans: "அனேஜதேகம் மனஸோ ஜவீயோ நைனத்தேவா ஆப்னுவன் பூர்வமர்ஷத் |\nதத்தாவதோ'ன்யான் அத்யேதி திஷ்டத் தஸ்மின்னபோ மாதரிஶ்வா ததாதி || 4 ||", english: "The Self is one, unmoving, swifter than the mind. The senses cannot overtake It. Standing still, It passes those who run.", commentary_tamil: "ஆத்மா அசைவற்றது ஆனால் மனதை விட வேகமானது. புலன்களால் அதை எட்ட முடியாது.", commentary_english: "The Self transcends time, space, and senses." },
            { id: 5, sanskrit: "तदेजति तन्नैजति तद्दूरे तद्वन्तिके ।\nतदन्तरस्य सर्वस्य तदु सर्वस्यास्य बाह्यतः ॥ ५॥", tamil_trans: "ததேஜதி தன்னைஜதி தத்தூரே தத்வந்திகே |\nததந்தரஸ்ய ஸர்வஸ்ய தது ஸர்வஸ்யாஸ்ய பாஹ்யத: || 5 ||", english: "It moves, and It moves not. It is far, and It is near. It is within all this, and It is outside all this.", commentary_tamil: "அது அசைவது, அசையாதது. தூரமானது, மிக அருகிலானது. உள்ளும் புறமும் நிறைந்தது.", commentary_english: "Brahman is omnipresent and beyond contradictory attributes." },
            { id: 6, sanskrit: "यस्तु सर्वाणि भूतानि आत्मन्येवानुपश्यति ।\nसर्वभूतेषु चात्मानं ततो न विजुगुप्सते ॥ ६॥", tamil_trans: "யஸ்து ஸர்வாணி பூதானி ஆத்மன்யேவானுபச்யதி |\nஸர்வபூதேஷு சாத்மானம் ததோ ந விஜுகுப்ஸதே || 6 ||", english: "He who sees all beings in the Self and the Self in all beings feels no hatred.", commentary_tamil: "எல்லா உயிர்களிலும் இறைவனைக் காண்பவன் யாரையும் வெறுப்பதில்லை.", commentary_english: "Universal Oneness dispels hatred." },
            { id: 7, sanskrit: "यस्मिन् सर्वाणि भूतानि आत्मैवाभूद् विजानतः ।\nतत्र को मोहः कः शोक एकत्वमनुपश्यतः ॥ ७॥", tamil_trans: "யஸ்மின் ஸர்வாணி பூதானி ஆத்மைவாபூத் விஜானத: |\nதத்ர கோ மோஹ: க: ஶோக ஏகத்வமானுபச்யத: || 7 ||", english: "When to the knower all beings have become the Self, what delusion or sorrow is there for one who sees oneness?", commentary_tamil: "எல்லாம் ஒன்றே என்று உணர்பவனுக்கு துக்கமோ மோகமோ இல்லை.", commentary_english: "Realization of Oneness removes sorrow and delusion." },
            { id: 8, sanskrit: "स पर्यगाच्छुक्रमकायमव्रणम् अस्नाविरँ शुद्धमपापविद्धम् ।\nकविर्मनीषी परिभूः स्वयम्भूः याथातथ्यतोऽर्थान् व्यदधात् शाश्वतीभ्यः समाभ्यः ॥ ८॥", tamil_trans: "ஸ பர்யகா ச்சுக்ர மகாய மவ்ரணம் அஸ்னாவிரம் ஶுத்தம் அபாப வித்தம் |\nகவிர் மனீஷீ பரிபூ: ஸ்வயம்பூ: யாதாதத்யதோ'ர்த்தான் வ்யததாத் ஶாஶ்வதீப்ய: ஸமாப்ய: || 8 ||", english: "He (the Self) is all-pervasive, radiant, bodiless, pure, and untouched by sin. He is the Seer, the Thinker, the Self-existent.", commentary_tamil: "ஆத்மா ஒளிமயமானது, உருவற்றது, தூயது. அதுவே எல்லாவற்றையும் ஆள்கிறது.", commentary_english: "Nature of the Supreme Self: Pure and Self-existent." },
            { id: 9, sanskrit: "अन्धं तमः प्रविशन्ति येऽविद्यामुपासते ।\nततो भूय इव ते तमो य उ विद्यायां रताः ॥ ९॥", tamil_trans: "அந்தம் தம: ப்ரவிஶந்தி யே'வித்யாமுபாஸதே |\nததோ பூய இவ தே தமோ ய உ வித்யாயாம் ரதா: || 9 ||", english: "Into blinding darkness enter those who worship ignorance (rituals only). Into greater darkness enter those who are engrossed in knowledge (theory only).", commentary_tamil: "கர்மாவை மட்டும் நம்புபவர்கள் இருளில் செல்கிறார்கள். வெறும் அறிவை மட்டும் நம்புபவர்கள் அதைவிட பெரிய இருளில் சொல்கிறார்கள்.", commentary_english: "Balance between Action (Karma) and Knowledge (Vidya) is needed." },
            { id: 10, sanskrit: "अन्यदेवाहुर्विद्यया अन्यदाहुरविद्यया ।\nइति शुश्रुम धीराणां ये नस्तद्व्याचचक्षिरे ॥ १०॥", tamil_trans: "அன்யதேவாஹுர் வித்யயா அன்யதாஹுர் அவித்யயா |\nஇதி ஶுஶ்ரும தீராணாம் யே நஸ்தத் வ்யாசசக்ஷிரே || 10 ||", english: "One result comes from knowledge, and another from ignorance. Thus we have heard from the wise.", commentary_tamil: "வித்தை மற்றும் அவித்தை ஒவ்வொன்றும் வெவ்வேறு பலன்களைத் தருகின்றன.", commentary_english: "Distinction between the path of knowledge and the path of rituals." },
            { id: 11, sanskrit: "विद्यां चाविद्यां च यस्तद्वेदोभयँ सह ।\nअविद्यया मृत्युं तीर्त्वा विद्ययामृतमश्नुते ॥ १॥", tamil_trans: "வித்யாம் சாவித்யாம் ச யஸ்தத் வேதோபயம் ஸஹ |\nஅவித்யயா ம்ருத்யும் தீர்த்வா வித்யயாம்ருத மஶ்னுதே || 11 ||", english: "He who knows both Vidya (knowledge) and Avidya (rites) together crosses death through Avidya and attains immortality through Vidya.", commentary_tamil: "கர்மா மூலம் மரணத்தை வென்று, ஞானம் மூலம் மோட்சத்தை அடையலாம்.", commentary_english: "Integrating Karma and Jnana leads to liberation." },
            { id: 12, sanskrit: "अन्धं तमः प्रविशन्ति येऽसंभूतिमुपासते ।\nततो भूय इव ते तमो य उ संभूत्याँ रताः ॥ १२॥", tamil_trans: "அந்தம் தம: ப்ரவிஶந்தி யே'ஸம்பூதிமுபாஸதே |\nததோ பூய இவ தே தமோ ய உ ஸம்பூத்யாம் ரதா: || 12 ||", english: "Those who worship the Unmanifest (Nature) enter darkness. Those who worship the Manifest (Hiranyagarbha) enter greater darkness.", commentary_tamil: "இயற்கையை மட்டும் வழிபடுபவர்கள் இருளை அடைகிறார்கள்.", commentary_english: "Worship of the relative vs. the absolute." },
            { id: 13, sanskrit: "अन्यदेवाहुः संभवादन्यदाहुरसंभवात् ।\nइति शुश्रुम धीराणां ये नस्तद्व्याचचक्षिरे ॥ १३॥", tamil_trans: "அன்யதேவாஹு: ஸம்பவாத் அன்யதாஹுர் அஸம்பவாத் |\nஇதி ஶுஶ்ரும தீராணாம் யே நஸ்தத் வ்யாசசக்ஷிரே || 13 ||", english: "Different results are obtained from the Manifest and the Unmanifest. Thus we have heard from the wise.", commentary_tamil: "வெளிப்படையான மற்றும் மறைமுகமான வழிபாடுகளின் பலன்கள் வெவ்வேறானவை.", commentary_english: "Different paths yield different temporary results." },
            { id: 14, sanskrit: "संभूतिं च विनाशं च यस्तद्वेदोभयँ सह ।\nविनाशेन मृत्युं तीर्त्वा संभूत्यामृतमश्नुते ॥ १४॥", tamil_trans: "ஸம்பூதிம் ச விநாஶம் ச யஸ்தத் வேதோபயம் ஸஹ |\nவிநாஶேன ம்ருத்யும் தீர்த்வா ஸம்பூத்யாம்ருத மஶ்னுதே || 14 ||", english: "He who knows both the Manifest and Destruction crosses death through Destruction and attains immortality through the Manifest.", commentary_tamil: "படைப்பு மற்றும் அழிவு இரண்டையும் அறிவது முக்கியம்.", commentary_english: "Understanding the cycle of creation and dissolution." },
            { id: 15, sanskrit: "हिरण्मयेन पात्रेण सत्यस्यापिहितं मुखम् ।\nतत्त्वं पूषन्नपावृणु सत्यधर्माय दृष्टये ॥ १५॥", tamil_trans: "ஹிரண்மயேன பாத்ரேண ஸத்யஸ்யாபிஹிதம் முகம் |\nதத் த்வம் பூஷன் அபாவ்ருணு ஸத்யதர்மாய த்ருஷ்டயே || 15 ||", english: "The face of Truth is covered by a golden lid. O Pusan (Sun), uncover it so that I, who am devoted to Truth, may see it.", commentary_tamil: "பொன்மயமான தட்டினால் உண்மையின் முகம் மூடப்பட்டுள்ளது. சூரியனே, அதை விலக்குவாயாக.", commentary_english: "Prayer to remove the glitter of the material world to see the Truth." },
            { id: 16, sanskrit: "पूषन्नेकर्षे यम सूर्य प्राजापत्य व्यूह रश्मीन् समूह ।\nतेजो यत्ते रूपं कल्याणतमं तत्ते पश्यामि योऽसावसौ पुरुषः सोऽहमस्मि ॥ १६॥", tamil_trans: "பூஷன்னேகர்ஷே யம ஸூர்ய ப்ராஜபத்ய வ்யூஹ ரஶ்மீன் ஸமூஹ |\nதேஜோ யத்தே ரூபம் கல்யாணதமம் தத்தே பச்யாமி யோ'ஸாவஸௌ புருஷ: ஸோ'ஹமஸ்மி || 16 ||", english: "O Nourisher, O Sun, gather thy rays. I see thy most auspicious form. That Purusha who is there, He am I.", commentary_tamil: "உன் ஒளியை சுருக்கிக்கொள். உன்னில் உள்ள அந்த புருஷன் நானே (சோஹம்).", commentary_english: "The realization 'Soham' (I am He)." },
            { id: 17, sanskrit: "वायुरनिलममृतमथेदं भस्मान्तँ शरीरम् ।\nॐ क्रतो स्मर कृतं स्मर क्रतो स्मर कृतं स्मर ॥ १७॥", tamil_trans: "வாயுரநிலம் அம்ருதம் அதேதம் பஸ்மாந்தம் ஶரீரம் |\nஓம் க்ரதோ ஸ்மர க்ருதம் ஸ்மர க்ரதோ ஸ்மர க்ருதம் ஸ்மர || 17 ||", english: "May this life enter the immortal Breath; may this body be reduced to ashes. O mind, remember what has been done. Remember!", commentary_tamil: "உடல் அழியும், பிராணன் இறைவனை அடையட்டும். மனமே, செய்த நன்மைகளை நினை.", commentary_english: "Final prayer at the time of death." },
            { id: 18, sanskrit: "अग्ने नय सुपथा राये अस्मान् विश्वानि देव वयुनानि विद्वान् ।\nयुयोध्यस्मज्जुहुराणमेनो भूयिष्ठां ते नम उक्तिं विधेम ॥ १८॥", tamil_trans: "அக்னே நய ஸுபதா ராயே அஸ்மான் விஶ்வானி தேவ வயுனானி வித்வான் |\nயுயோத்யஸ்மஜ் ஜுஹுராணமேனோ பூயிஷ்டாம் தே நம உக்திம் விதேம || 18 ||", english: "O Agni, lead us by the good path to prosperity. You know all our deeds. Remove from us the sin that leads astray. We offer you many prostrations.", commentary_tamil: "அக்னியே, எங்களை நல்வழியில் அழைத்துச் செல். பாவங்களை நீக்கு. உன்னை வணங்குகிறோம்.", commentary_english: "Prayer for guidance and purification." }
        ]
    },
    {
        id: "mandukya",
        title: "Mandukya Upanishad (மாண்டூக்யோபனிஷத்)",
        subtitle: "Consciousness & OM (Full 12 Mantras)",
        shanti_mantra: { sanskrit: "ॐ भद्रं कर्णेभिः शृणुयाम देवाः ।\nभद्रं पश्येमाक्षभिर्यजत्राः ।\nस्थिरैरङ्गैस्तुष्टुवांसस्तनूभिः ।\nव्यशेम देवहितं यदायुः ॥\nॐ शान्तिः शान्तिः शान्तिः ॥", tamil_trans: "ஓம் பத்ரம் கர்ணேபி: ஶ்ருணுயாம தேவா: |\nபத்ரம் பஶ்யேமாக்ஷபிர்யஜத்ரா: |\nஸ்திரைரங்கைஸ்துஷ்டுவாம்ஸஸ்தனூபி: |\nவ்யஶேம தேவஹிதம் யதாயு: ||\nஓம் சாந்தி: சாந்தி: சாந்தி: ||", english: "Om. Ye Gods, may we hear with our ears what is auspicious. May we see with our eyes what is auspicious. Praising with steady limbs and bodies, may we enjoy the life allotted by the Gods. Om Peace, Peace, Peace." },
        verses: [
            { id: 1, sanskrit: "ओमित्येतदक्षरमिदँ सर्वं तस्योपव्याख्यानं भूतं भवद्भविष्यदिति सर्वमोङ्कार एव ।\nयच्चान्यत्त्रिकालातीतं तदप्योङ्कार एव ॥ १॥", tamil_trans: "ஓம் இத்யேததக்ஷரமிதம் ஸர்வம் தஸ்யோபவ்யாக்யானம் பூதம் பவத்பவிஷ்யதிதி ஸர்வமோங்கார ஏவ |\nயச்சான்யத் த்ரிகாலாதீதம் ததப்யோங்கார ஏவ || 1 ||", english: "OM! This Syllable is all this. An explanation of that is the following: All that is past, present, and future is verily OM. That which is beyond the three periods of time is also verily OM.", commentary_tamil: "'ஓம்' என்ற மந்திரமே அனைத்தும். காலத்தைக் கடந்ததும் அதுவே.", commentary_english: "OM represents the entire universe and what lies beyond time." },
            { id: 2, sanskrit: "सर्वं ह्येतद् ब्रह्मायमात्मा ब्रह्म सोऽयमात्मा चतुष्पात् ॥ २॥", tamil_trans: "ஸர்வம் ஹ்யேதத் ப்ரஹ்மாயமாத்மா ப்ரஹ்ம ஸோ'யமாத்மா சதுஷ்பாத் || 2 ||", english: "All this is specified as Brahman. This Atman (Self) is Brahman. This Atman has four quarters (padas).", commentary_tamil: "எல்லாமே பிரம்மம். இந்த ஆத்மாவே பிரம்மம். அதற்கு நான்கு நிலைகள் உண்டு.", commentary_english: "Ayam Atma Brahma (This Self is God). The Self has four aspects." },
            { id: 3, sanskrit: "जागरितस्थानो बहिष्प्रज्ञः सप्ताङ्ग एकोनविंशतिमुखः स्थूलभुग्वैश्वानरः प्रथमः पादः ॥ ३॥", tamil_trans: "ஜாகரிதஸ்தானோ பஹிஷ்ப்ரக்ஞ: ஸப்தாங்க ஏகோனவிம்ஶதிமுக: ஸ்தூலபுக்வைஶ்வானர: பிரதம: பாத: || 3 ||", english: "The first quarter is Vaishvanara, whose sphere is the waking state, who is conscious of the external world, who has seven limbs and nineteen mouths, and who experiences gross objects.", commentary_tamil: "முதல் நிலை: வைச்வானரன் (விழி்ப்பு நிலை). வெளி உலகை அறிபவன்.", commentary_english: "Waking State (Jagrat): Experiencing the external physical world." },
            { id: 4, sanskrit: "स्वप्नस्थानोऽन्तःप्रज्ञः सप्ताङ्ग एकोनविंशतिमुखः प्रविविक्तभुक्तैजसो द्वितीयः पादः ॥ ४॥", tamil_trans: "ஸ்வப்னஸ்தானோ'ந்த:ப்ரக்ஞ: ஸப்தாங்க ஏகோனவிம்ஶதிமுக: ப்ரவிவிக்தபுக் தைஜஸோ த்விதீய: பாத: || 4 ||", english: "The second quarter is Taijasa, whose sphere is the dream state, who is conscious of the internal world, who has seven limbs and nineteen mouths, and who experiences subtle objects.", commentary_tamil: "இரண்டாம் நிலை: தைஜஸன் (கனவு நிலை). உள் மனதை அறிபவன்.", commentary_english: "Dream State (Swapna): Experiencing the internal subtle world." },
            { id: 5, sanskrit: "यत्र सुप्तो न कञ्चन कामं कामयते न कञ्चन स्वप्नं पश्यति तत्सुषुप्तम् ।\nसुषुप्तस्थान एकीभूतः प्रज्ञानघन एवाऽऽनन्दमयो ह्यानन्दभुक् चेतोमुखः प्राज्ञस्तृतीयः पादः ॥ ५॥", tamil_trans: "யத்ர ஸுப்தோ ந கஞ்சன காமம் காமயதே ந கஞ்சன ஸ்வப்னம் பஶ்யதி தத்ஸுஷுப்தம் |\nஸுஷுப்தஸ்தான ஏகீபூத: ப்ரக்ஞானகன ஏவா'னந்தமயோ ஹ்யானந்தபுக் சேதோமுக: ப்ராக்ஞஸ்த்ருதீய: பாத: || 5 ||", english: "That is the state of deep sleep wherein one desires nothing and sees no dreams. The third quarter is Prajna, whose sphere is deep sleep, who has become one, who is a mass of consciousness, who is full of bliss and experiences bliss, and who is the gateway to experience.", commentary_tamil: "மூன்றாம் நிலை: ப்ராக்ஞன் (ஆழ்ந்த உறக்கம்). ஆனந்த வடிவானவன்.", commentary_english: "Deep Sleep State (Sushupti): Mass of undifferentiated consciousness and bliss." },
            { id: 6, sanskrit: "एष सर्वेश्वर एष सर्वज्ञ एषोऽन्तर्याम्येष योनिः सर्वस्य प्रभवाप्ययौ हि भूतानाम् ॥ ६॥", tamil_trans: "ஏஷ ஸர்வேஶ்வர ஏஷ ஸர்வக்ஞ ஏஷோ'ந்தர்யாம்யேஷ யோனி: ஸர்வஸ்ய ப்ரபவாப்யயௌ ஹி பூதானாம் || 6 ||", english: "This is the Lord of all, the Omniscient, the Indwelling Controller, the Source of all. This is the beginning and end of all beings.", commentary_tamil: "இவனே அனைத்தையும் ஆள்பவன், எல்லாம் அறிந்தவன் (ஈஸ்வரன்).", commentary_english: "Description of Ishvara, the Creator and Controller." },
            { id: 7, sanskrit: "नान्तःप्रज्ञं न बहिष्प्रज्ञं नोभयतःप्रज्ञं न प्रज्ञानघनं न प्रज्ञं नाप्रज्ञम् ।\nअदृष्टमव्यवहार्यमग्राह्यमलक्षणमचिन्त्यमव्यपदेश्यमेकात्मप्रत्ययसारं प्रपञ्चोपशमं शान्तं शिवमद्वैतं चतुर्थं मन्यन्ते स आत्मा स विज्ञेयः ॥ ७॥", tamil_trans: "நாந்த:ப்ரக்ஞம் ந பஹிஷ்ப்ரக்ஞம் நோபயத:ப்ரக்ஞம் ந ப்ரக்ஞானகனம் ந ப்ரக்ஞம் நாப்ரக்ஞம் |\nஅத்ருஷ்டமவ்யவஹார்யமக்ராஹ்யமலக்ஷணம சிந்த்யமவ்யபதேஶ்யமேகாத்மப்ரத்யயஸாரம் ப்ரபஞ்சோபஶமம் ஶாந்தம் ஶிவமத்வைதம் சதுர்த்தம் மன்யந்தே ஸ ஆத்மா ஸ விக்ஞேய: || 7 ||", english: "They consider the Fourth (Turiya) to be that which is not inwardly conscious, not outwardly conscious, not conscious of both, not a mass of consciousness, not conscious, not unconscious. It is unseen, unrelated, incomprehensible, uninferable, unthinkable, indescribable, the essence of the Consciousness manifesting as the self in the three states, the cessation of all phenomena, all peace, all bliss and non-dual. That is the Atman, and that is to be realized.", commentary_tamil: "நான்காம் நிலை: துரியம். இதுவே உண்மையான ஆத்மா. அமைதியானது, மங்களகரமானது, இரண்டற்றது (அத்வைதம்).", commentary_english: "Turiya: The Pure Consciousness beyond the three states. The Real Self." },
            { id: 8, sanskrit: "सोऽयमात्माध्यक्षरमोङ्कारोऽधिमात्रं पादा मात्रा मात्राश्च पादा अकार उकारो मकार इति ॥ ८॥", tamil_trans: "ஸோ'யமாத்மாத்யக்ஷரமோங்காரோ'திமாத்ரம் பாதா மாத்ரா மாத்ராஶ்ச பாதா அகார உகாரோ மகார இதி || 8 ||", english: "This same Atman, from the standpoint of the syllable, is OM. The quarters are the letters (matras) and the letters are the quarters: the letter A, the letter U, and the letter M.", commentary_tamil: "ஓம் மந்திரத்தின் மூன்று எழுத்துக்களே (அ, உ, ம) ஆத்மாவின் மூன்று நிலைகள்.", commentary_english: "Correlation between OM and the three states of consciousness." },
            { id: 9, sanskrit: "जागरितस्थानो वैश्वानरोऽकारः प्रथमा मात्रा ...", tamil_trans: "ஜாகரிதஸ்தானோ வைஶ்வானரோ'கார: பிரதமா மாத்ரா ...", english: "Vaishvanara (Waking) is the letter 'A', the first letter...", commentary_tamil: "விழிப்பு நிலை - அகாரம் ('அ').", commentary_english: "'A' represents the Waking State." },
            { id: 10, sanskrit: "स्वप्नस्थानस्तैजस उकारो द्वितीया मात्रा ...", tamil_trans: "ஸ்வப்னஸ்தானஸ் தைஜஸ உகாரோ த்விதீயா மாத்ரா ...", english: "Taijasa (Dream) is the letter 'U', the second letter...", commentary_tamil: "கனவு நிலை - உகாரம் ('உ').", commentary_english: "'U' represents the Dream State." },
            { id: 11, sanskrit: "सुषुप्तस्थानः प्राज्ञो मकारस्तृतीया मात्रा ...", tamil_trans: "ஸுஷுப்தஸ்தான: ப்ராக்ஞோ மகாரஸ்த்ருதீயா மாத்ரா ...", english: "Prajna (Deep Sleep) is the letter 'M', the third letter...", commentary_tamil: "ஆழ்ந்த உறக்கம் - மகாரம் ('ம்').", commentary_english: "'M' represents the Deep Sleep State." },
            { id: 12, sanskrit: "अमात्रश्चतुर्थोऽव्यवहार्यः प्रपञ्चोपशमः शिवोऽद्वैत एवमोङ्कार आत्मैव संविशत्यात्मनाऽऽत्मानं य एवं वेद य एवं वेद ॥ १२॥", tamil_trans: "அமாத்ரஶ்சதுர்த்தோ'வ்யவஹார்ய: ப்ரபஞ்சோபஶம: ஶிவோ'த்வைத ஏவமோங்கார ஆத்மைவ ஸம்விஶத்யாத்மனா''த்மானம் ய ஏவம் வேத ய ஏவம் வேத || 12 ||", english: "That which has no part (soundless aspect) is the Fourth, the Incomprehensible, the Cessation of all phenomena, All-Bliss and Non-Dual. Thus OM is verily the Atman. He who knows this merges his self in the Self.", commentary_tamil: "மாத்திரையற்ற நான்காம் நிலை (அமாத்ரா) துரியம். இதை அறிபவன் பரமாத்மாவுடன் இணைகிறான்.", commentary_english: "The Silence after OM is Turiya. Realizing this leads to Mocksha." }
        ]
    },
    {
        id: "kena",
        title: "Kena Upanishad (கேனோபனிஷத்)",
        subtitle: "The Nature of Brahman (Full 4 Khandas)",
        shanti_mantra: {
            sanskrit: "ॐ आप्यायन्तु ममाङ्गानि वाक्प्राणश्चक्षुः श्रोत्रमथो बलमिन्द्रियाणि च सर्वाणि ।\nसर्वं ब्रह्मौपनिषदं माऽहं ब्रह्म निराकुर्यां मा मा ब्रह्म निराकरोदनिराकरणमस्त्वनिराकरणं मेऽस्तु ।\nतदात्मनि निरते य उपनिषत्सु धर्मास्ते मयि सन्तु ते मयि सन्तु ॥\nॐ शान्तिः शान्तिः शान्तिः ॥",
            tamil_trans: "ஓம் ஆப்யாயந்து மமாங்கானி வாக்ப்ராணஶ்சக்ஷு: ஶ்ரோத்ரமதோ பலமிந்த்ரியாணி ச ஸர்வாணி |\nஸர்வம் ப்ரஹ்மௌபநிஷதம் மா'ஹம் ப்ரஹ்ம நிராகுர்யாம் மா மா ப்ரஹ்ம நிராகரோத நிராகரணமஸ்த்வ நிராகரணம் மே'ஸ்து |\nததாத்மனி நிரதே ய உபநிஷத்ஸு தர்மாஸ்தே மயி ஸந்து தே மயி ஸந்து ||\nஓம் சாந்தி: சாந்தி: சாந்தி: ||",
            english: "Om. May my limbs, speech, Prana, eye, ear, strength, and all my senses become vigorous. All is the Brahman of the Upanishads. May I never deny Brahman. May Brahman never deny me. May there be no denial... Om Peace, Peace, Peace."
        },
        verses: [
            // --- Khanda 1 ---
            { id: "1.1", sanskrit: "ॐ केनेषितं पतति प्रेषितं मनः । केन प्राणः प्रथमः प्रैति युक्तः ।\nकेनेषितां वाचमिमां वदन्ति । चक्षुः श्रोत्रं क उ देवो युनक्ति ॥ १॥", tamil_trans: "ஓம் கேனேஷிதம் பததி ப்ரேஷிதம் மன: | கேன ப்ராண: பிரதம: ப்ரைதி யுக்த: |\nகேனேஷிதாம் வாசமிமாம் வதந்தி | சக்ஷு: ஶ்ரோத்ரம் க உ தேவோ யுனக்தி || 1 ||", english: "By whom willed and directed does the mind light upon its objects? By whom commanded does life the first, move? At whose will do (people) utter this speech? And what god prompts the eye and the ear?", commentary_tamil: "முதல் கண்டம்: மனதையும் புலன்களையும் இயக்குவது யார்?", commentary_english: "Khanda 1: Inquiry into the source of consciousness." },
            { id: "1.2", sanskrit: "श्रोत्रस्य श्रोत्रं मनसो मनो यत् । वाचो ह वाचं स उ प्राणस्य प्राणः ।\nचक्षुषश्चक्षुरतिमुच्य धीराः । प्रेत्यास्माल्लोकादमृता भवन्ति ॥ २॥", tamil_trans: "ஶ்ரோத்ரஸ்ய ஶ்ரோத்ரம் மனஸோ மனோ யத் | வாசோ ஹ வாசம் ஸ உ ப்ராணஸ்ய ப்ராண: |\nசக்ஷுஷஶ்சக்ஷுரதிமுச்ய தீரா: | ப்ரேத்யாஸ்மால்லோகாத் அம்ருதா பவந்தி || 2 ||", english: "It is the Ear of the ear, the Mind of the mind, the Speech of speech, the Breath of the breath, and the Eye of the eye. The wise, separating themselves from these, become immortal.", commentary_tamil: "புலன்களின் சக்தியும் பிரம்மமே. இதை உணர்ந்தவர் மரணமில்லா வாழ்வை அடைகிறார்.", commentary_english: "Brahman is the Subject, the witness of all senses." },
            { id: "1.3", sanskrit: "न तत्र चक्षुर्गच्छति न वाग्गच्छति नो मनः ।\nन विद्मो न विजानीमो यथैतदनुशिष्यात् ॥ ३॥", tamil_trans: "ந தத்ர சக்ஷுர்கச்சதி ந வாக்கச்சதி நோ மன: |\nந வித்மோ ந விஜானீமோ யதைததனுஶிஷ்யாத் || 3 ||", english: "There the eye goes not, speech goes not, nor the mind. We know not, we understand not, how one can teach this.", commentary_tamil: "கண்ணும் மனமும் அங்கே செல்ல முடியாது. அதை விளக்க வழி தெரியவில்லை.", commentary_english: "Brahman is beyond sensory perception and intellect." },
            { id: "1.4", sanskrit: "अन्यदेव तद्विदितादथो अविदितादधि ।\nइति शुश्रुम पूर्वेषां ये नस्तद्व्याचचक्षिरे ॥ ४॥", tamil_trans: "அன்யதேவ தத்விதி தாததோ அவிதி தாததி |\nஇதி ஶுஶ்ரும பூர்வேஷாம் யே நஸ்தத் வ்யாசசக்ஷிரே || 4 ||", english: "It is distinct from the known and also beyond the unknown. Thus we have heard from the ancients who taught us this.", commentary_tamil: "தெரிந்தவற்றுக்கும் தெரியாதவற்றுக்கும் அப்பாற்பட்டது அது.", commentary_english: "Brahman is neither an object of knowledge nor unknown." },
            { id: "1.5", sanskrit: "यद्वाचानभ्युदितं येन वागभ्युद्यते ।\nतदेव ब्रह्म त्वं विद्धि नेदं यदिदमुपासते ॥ ५॥", tamil_trans: "யத்வாசானப்யுதிதம் யேன வாகப்யுத்யதே |\nததேவ ப்ரஹ்ம த்வம் வித்தி நேதம் யதிதமுபாஸதே || 5 ||", english: "That which is not expressed by speech, but by which speech is expressed - know that alone to be Brahman, not this which people worship here.", commentary_tamil: "வாக்கினால் சொல்ல முடியாதது, ஆனால் வாக்கை வெளிப்படுத்துவது எதுவோ அதுவே பிரம்மம்.", commentary_english: "Brahman is the enabler of speech, not the object of speech." },
            { id: "1.6", sanskrit: "यन्मनसा न मनुते येनाहुर्मनो मतम् ।\nतदेव ब्रह्म त्वं विद्धि नेदं यदिदमुपासते ॥ ६॥", tamil_trans: "யன்மனஸா ந மனுதே யேனாஹுர் மனோ மதம் |\nததேவ ப்ரஹ்ம த்வம் வித்தி நேதம் யதிதமுபாஸதே || 6 ||", english: "That which is not thought by the mind, but by which the mind thinks - know that alone to be Brahman.", commentary_tamil: "மனதால் நினைக்க முடியாதது, ஆனால் மனதை நினைக்க வைப்பது அதுவே.", commentary_english: "The Thinker cannot be thought." },
            { id: "1.7", sanskrit: "यच्चक्षुषा न पश्यति येन चक्षूंषि पश्यति ।\nतदेव ब्रह्म त्वं विद्धि नेदं यदिदमुपासते ॥ ७॥", tamil_trans: "யச்சக்ஷுஷா ந பஶ்யதி யேன சக்ஷூம்ஷி பஶ்யதி |\nததேவ ப்ரஹ்ம த்வம் வித்தி நேதம் யதிதமுபாஸதே || 7 ||", english: "That which is not seen by the eye, but by which the eye sees - know that alone to be Brahman.", commentary_tamil: "கண்ணால் பார்க்க முடியாதது, ஆனால் கண்ணை பார்க்க வைப்பது அதுவே.", commentary_english: "The Seer cannot be seen." },
            { id: "1.8", sanskrit: "यच्छ्रोत्रेण न शृणोति येन श्रोत्रमिदं श्रुतम् ।\nतदेव ब्रह्म त्वं विद्धि नेदं यदिदमुपासते ॥ ८॥", tamil_trans: "யச்ச்ரோத்ரேண ந ஶ்ருணோதி யேன ஶ்ரோத்ர மிதம் ஶ்ருதம் |\nததேவ ப்ரஹ்ம த்வம் வித்தி நேதம் யதிதமுபாஸதே || 8 ||", english: "That which is not heard by the ear, but by which the ear hears - know that alone to be Brahman.", commentary_tamil: "காதால் கேட்க முடியாதது, ஆனால் காதை கேட்க வைப்பது அதுவே.", commentary_english: "The Hearer cannot be heard." },

            // --- Khanda 2 ---
            { id: "3.7-10", sanskrit: "अथ वायुमब्रुवन् ...", tamil_trans: "அத வாயுமப்ருவன் ...", english: "Then Vayu went. 'I can blow away everything.' But he could not move the straw.", commentary_tamil: "வாயு தேவனாலும் அந்தப் புல்லை அசைக்க முடியவில்லை.", commentary_english: "Vayu fails." },
            { id: "3.11-12", sanskrit: "अथेन्द्रमब्रुवन् ... तस्मात्तिरोदधे ॥", tamil_trans: "தேந்த்ரமப்ருவன் ...", english: "Then Indra rushed to It. It disappeared from him.", commentary_tamil: "இந்திரன் சென்றான். யட்சன் மறைந்து விட்டான்.", commentary_english: "Indra approaches." },

            // --- Khanda 4 ---
            { id: "4.1", sanskrit: "स तस्मिन्नेवाकाशे स्त्रियमागमद्बहुशोभमानामुमां हैमवतीं ...", tamil_trans: "ஸ தஸ்மின்னேவாகாஶே...", english: "In that space appearing a Goddess, Uma Haimavati. Indra asked her: 'Who is this Spirit?'", commentary_tamil: "நான்காம் கண்டம்: உமா தேவி தோன்றினாள்.", commentary_english: "Khanda 4: Uma teaches Indra." },
            { id: "4.2", sanskrit: "सा ब्रह्मेति होवाच ब्रह्मणो वा एतद्विजये महीयध्वमिति ...", tamil_trans: "ஸா ப்ரஹ்மேதி ஹோவாச...", english: "She said: 'It is Brahman. In Brahman's victory alone you are great.'", commentary_tamil: "'அதுவே பிரம்மம்' என்று அவள் கூறினாள்.", commentary_english: "Revelation of Brahman." },
            { id: "4.4", sanskrit: "तस्माद्वा इन्द्रोऽतिशयानिवान्यन्देवान् ...", tamil_trans: "தஸ்மாத்வா இந்த்ரோ...", english: "Therefore Indra is superior to other gods, for he first knew It was Brahman.", commentary_tamil: "இந்திரனே முதலில் அறிந்தான்.", commentary_english: "Indra's greatness." },
            { id: "4.8", sanskrit: "तस्यै तपो दमः कर्मेति प्रतिष्ठा वेदाः सर्वाङ्गानि सत्यमायतनम् ॥ ८॥", tamil_trans: "தஸ்யை தபோ தம: கர்மேதி ப்ரதிஷ்டா...", english: "Austerity, self-control, and work are its support. The Vedas are its limbs. Truth is its abode.", commentary_tamil: "தவம், கட்டுப்பாடு, கர்மா இவையே அஸ்திவாரம். வாய்மையே அதன் இருப்பிடம்.", commentary_english: "Foundations of knowledge." }
        ]
    },
    {
        id: "katha",
        title: "Katha Upanishad (கடோபனிஷத்)",
        subtitle: "The Secret of Death (Full Text)",
        shanti_mantra: {
            sanskrit: "ॐ सह नाववतु । सह नौ भुनक्तु । सह वीर्यं करवावहै ।\nतेजस्वि नावधीतमस्तु मा विद्विषावहै ॥\nॐ शान्तिः शान्तिः शान्तिः ॥",
            tamil_trans: "ஓம் ஸஹ நாவவது | ஸஹ நௌ புனக்து | ஸஹ வீர்யம் கரவாவஹை |\nதேஜஸ்வி நாவதீதமஸ்து மா வித்விஷாவஹை ||\nஓம் சாந்தி: சாந்தி: சாந்தி: ||",
            english: "Om. May He protect us both (Teacher and Student). May He nourish us both. May we work together with great energy. May our study be enlightening and not give rise to hostility. Om Peace, Peace, Peace."
        },
        verses: [
            // --- Chapter 1, Valli 1 ---
            { id: "1.1.1", sanskrit: "उशन् ह वै वाजश्रवसः सर्ववेदसं ददौ ।\nतस्य ह नचिकेता नाम पुत्र आस ॥ १॥", tamil_trans: "உஶன் ஹ வை வாஜஶ்ரவஸ: ஸர்வவேதஸம் ததௌ |\nதஸ்ய ஹ நசிகேதா நாம புத்ர ஆஸ || 1 ||", english: "Desiring (heavenly rewards), Vajasravasa gave away all his possessions. He had a son named Nachiketa.", commentary_tamil: "வாஜஸ்ரவஸ் யாகம் செய்து தன் செல்வங்களை தானம் அளித்தார்.", commentary_english: "Vajasravasa's sacrifice." },
            { id: "1.1.2", sanskrit: "तँ ह कुमारँ सन्तं दक्षिणासु नीयमानासु श्रद्धाऽविवेश सोऽमन्यत ॥ २॥", tamil_trans: "தம் ஹ குமாரம் ஸந்தம் தக்ஷிணாஸு நீயமானாஸு ஶ்ரத்தா'விவேஶ ஸோ'மன்யத || 2 ||", english: "When the gifts (cows) were being led away, faith entered the young boy Nachiketa, and he thought:", commentary_tamil: "நசிகேதனுக்கு சிந்தனை தோன்றியது.", commentary_english: "Nachiketa reflects on the offering." },
            { id: "1.1.3", sanskrit: "पीतोदका जग्धतृणा दुग्धदोहा निरिन्द्रियाः ।\nअनन्दा नाम ते लोकास्तान् स गच्छति ता ददत् ॥ ३॥", tamil_trans: "பீதோதகா ஜக்தத்ருணா துக்ததோஹா நிரில்ந்த்ரியா: |\nஅனந்தா நாம தே லோகாஸ்தான் ஸ கச்சதி தா ததத் || 3 ||", english: "Joyless are those worlds to which he goes who gives such cows—cows that have drunk their water, eaten their grass, given their milk, and are barren.", commentary_tamil: "பயனற்ற தானம் நரகத்தையே தரும்.", commentary_english: "Useless charity leads to joyless worlds." },
            { id: "1.1.4", sanskrit: "स होवाच पितरं तत कस्मै मां दास्यसीति ।\nद्वितीयं तृतीयं तँ होवाच मृत्यवे त्वा ददामीति ॥ ४॥", tamil_trans: "ஸ ஹோவாச பிதரம் தத கஸ்மை மாம் தாஸ்யஸீதி |\nத்விதீயம் த்ருதீயம் தம் ஹோவாச ம்ருத்யவே த்வா ததாமீதி || 4 ||", english: "He said to his father: 'Father, to whom will you give me?' He asked this twice and thrice. The father said in anger: 'I give you to Death.'", commentary_tamil: "'என்னை யாருக்குக் கொடுப்பீர்கள்?' என்ற கேள்விக்கு தந்தை 'எமனுக்கு' என்றார்.", commentary_english: "The father's angry vow." },
            { id: "1.1.5", sanskrit: "बहूनामेमि प्रथमो बहूनामेमि मध्यमः ।\nकिँ स्विद्यमस्य कर्तव्यं यन्मयाद्य करिष्यति ॥ ५॥", tamil_trans: "பஹூனாமேமி ப்ரதமோ பஹூனாமேமி மத்யம: |\nகிம் ஸ்வித்யமஸ்ய கர்தவ்யம் யன்மய அத்ய கரிஷ்யதி || 5 ||", english: "Nachiketa thought: 'Among many I go as the first; among many I go as the middle. What purpose of Yama will my father accomplish today through me?'", commentary_tamil: "நசிகேதன் சிந்திக்கிறான் - நான் எமலோகம் செல்வதால் என்ன பயன்?", commentary_english: "Nachiketa accepts his fate." },
            { id: "1.1.6", sanskrit: "अनुपश्य यथा पूर्वे प्रतिपश्य तथाऽपरे ।\nसस्यमिव मर्त्यः पच्यते सस्यमिवाजायते पुनः ॥ ६॥", tamil_trans: "அனுபச்ய யதா பூர்வே ப்ரதிபச்ய ததா'பரே |\nஸஸ்யமிவ மர்த்ய: பச்யதே ஸஸ்யமிவாஜாயதே புன: || 6 ||", english: "Look back at how the forefathers acted; look at those who are present. Like corn, a mortal ripens and falls; like corn, he is born again.", commentary_tamil: "மனிதன் பயிர் போல மடிந்து மீண்டும் பிறக்கிறான்.", commentary_english: "Cycle of life and death." },
            { id: "1.1.7", sanskrit: "वैश्वानरः प्रविशत्यतिथिर्ब्राह्मणो गृहान् ।\nतस्यैताँ शान्तिं कुर्वन्ति हर वैवस्वतोदकम् ॥ ७॥", tamil_trans: "வைஶ்வானர: ப்ரவிஶத்யதிதிர் ப்ராஹ்மணோ க்ருஹான் |\nதஸ்யைதாம் ஶாந்திம் குர்வந்தி ஹர வைவஸ்வதோதகம் || 7 ||", english: "A Brahmana guest enters a house like a fire. To appease him, they offer water explicitly. O Vaivasvata (Yama), bring water.", commentary_tamil: "விருந்தினர் அக்னி போன்றவர். அவருக்கு நீர் கொடுத்து உபசரிக்க வேண்டும்.", commentary_english: "Treating the guest as God." },
            { id: "1.1.8", sanskrit: "आशाप्रतीक्षे सङ्गतँ सूनृतां चेष्टापूर्ते पुत्रपशूँश्च सर्वान् ।\nएतद्वृङ्क्ते पुरुषस्याल्पमेधसो यस्यानश्नन्वसति ब्राह्मणो गृहे ॥ ८॥", tamil_trans: "ஆஶாப்ர்தீக்ஷே ஸங்கதம் ஸூன்ருதாம் சேஷ்டாபூர்தே புத்ரபஶூம்ஶ்ச ஸர்வான் |\nஏதத் வ்ருங்க்தே புருஷஸ்யல்பமேதஸோ யஸ்யானஶ்னன் வஸதி ப்ராஹ்மணோ க்ருஹே || 8 ||", english: "Hopes, expectations, friendship, truth, sacrifices, sons, and cattle—all are destroyed for the foolish man in whose house a Brahmana dwells fasting.", commentary_tamil: "விருந்தினரை பட்டினி போட்டால் புண்ணியம் அழியும்.", commentary_english: "Consequences of neglecting a guest." },
            { id: "1.1.9", sanskrit: "तिस्रो रात्रीर्यदवात्स्र्गृहे मेऽनश्नन् ब्रह्मन्नतिथिर्नमस्यः ।\nनमस्तेऽस्तु ब्रह्मन् स्वस्ति मेऽस्तु तस्मात्प्रति त्रीन्वरान्वृणीष्व ॥ ९॥", tamil_trans: "திஸ்ரோ ராத் தீர் யதவாத்ஸீர் க்ருஹே மே'னஶ்னன் ப்ரஹ்மன் அதிதிர் நமஸ்ய: |\nநமஸ்தே'ஸ்து ப்ரஹ்மன் ஸ்வஸ்தி மே'ஸ்து தஸ்மாத் ப்ரதி த்ரீன் வரான் வ்ருணீஷ்வ || 9 ||", english: "Yama said: 'O Brahmana, as you have lived in my house for three nights without food, I bow to you. May good befall me. Therefore, choose three boons.'", commentary_tamil: "எமன் மூன்று வரங்களை அளிக்கிறார்.", commentary_english: "Yama offers three boons." },
            { id: "1.1.10", sanskrit: "शान्तसङ्कल्पः सुमना यथा स्याद्वीतमन्युर्गौतमो माभि मृत्यो ।\nत्वत्प्रसृष्टं माभिवदेत्प्रतीत एतत् त्रयाणां प्रथमं वरं वृणे ॥ १०॥", tamil_trans: "ஶாந்தஸங்கல்ப: ஸுமனா யதா ஸ்யாத் வீதமன்யுர் கௌதமோ மாபி ம்ருத்யோ |\nத்வத்ப்ரஸ்ருஷ்டம் மாபிவதேத் ப்ரதீத ஏதத் த்ரயாணாம் ப்ரதமம் வரம் வ்ருணே || 10 ||", english: "Nachiketa said: 'O Death, may my father Gautama be free from anxiety, calm, and free from anger towards me. May he recognize and welcome me when sent back by you. This is the first boon.'", commentary_tamil: "முதல் வரம்: தந்தையின் கோபம் தணிய வேண்டும்.", commentary_english: "Boon 1: Father's peace." },
            { id: "1.1.11", sanskrit: "यथा पुरस्ताद् भविता प्रतीत औद्द्दालकिरारुणिर्मत्प्रसृष्टः ।\nसुखँ रात्रीः शययिता वीतमन्युः त्वां ददृशिवान्मृत्युमुखात् प्रमुक्तम् ॥ ११॥", tamil_trans: "யதா புரஸ்தாத் பவிதா ப்ரதீத ஔத்தாலகிர் ஆருணிர் மத்ப்ரஸ்ருஷ்ட: |\nஸுகம் ராத்ரீ: ஶயயிதா வீதமன்யு: த்வாம் தத்ருஶிவான் ம்ருத்யுமுகாத் ப்ரமுக்தம் || 11 ||", english: "Yama said: 'Auddalaki Aruni (your father) will be calm and recognize you. Seeing you released from the jaws of death, he will sleep peacefully.'", commentary_tamil: "எமன் முதல் வரத்தை அளிக்கிறார்.", commentary_english: "Yama grants Boon 1." },
            { id: "1.1.12", sanskrit: "स्वर्गे लोके न भयं किञ्चनास्ति न तत्र त्वं न जरया बिभेति ।\nउभे तीर्त्वा अशनायापिपासे शोकातिगो मोदते स्वर्गलोके ॥ १२॥", tamil_trans: "ஸ்வர்கே லோகே ந பயம் கிஞ்சனாஸ்தி ந தத்ர த்வம் ந ஜரயா பிபேதி |\nஉபே தீர்த்வா அஶனாயாபிபாஸே ஶோகாதிகோ மோததே ஸ்வர்கலோகே || 12 ||", english: "In Heaven there is no fear. You (Death) are not there, nor does one fear old age. Crossing hunger and thirst, leaving sorrow behind, one rejoices in Heaven.", commentary_tamil: "சொர்க்கத்தில் மரண பயம் இல்லை.", commentary_english: "Description of Heaven." },
            { id: "1.1.13", sanskrit: "स त्वमग्निँ स्वर्ग्यमध्येषि मृत्यो प्रब्रूहि त्वँ श्रद्दधानाय मह्यम् ।\nस्वर्गलोका अमृतत्वं भजन्त एतद् द्वितीयेन वृणे वरेण ॥ १३॥", tamil_trans: "ஸ த்வமக்னிம் ஸ்வர்க்யமத்யேஷி ம்ருத்யோ ப்ரப்ரூஹி த்வம் ஶ்ரத்ததானாய மஹ்யம் |\nஸ்வர்கலோகா அம்ருதத்வம் பஜந்த ஏதத் த்விதீயேன வ்ருணே வரேண || 13 ||", english: "O Death, you know the Fire Sacrifice that leads to Heaven. Teach it to me, for I have faith. This I choose as the second boon.'", commentary_tamil: "இரண்டாம் வரம்: ஸ்வர்க்கத்தை அளிக்கும் அக்னி வித்தையை அறிதல்.", commentary_english: "Boon 2: The Fire Sacrifice." },
            { id: "1.1.14", sanskrit: "प्र ते ब्रवीमि तदु मे निबोध स्वर्ग्यमग्निं नचिकेतः प्रजानन् ।\nअनन्तलोकाप्तिं अथो प्रतिष्ठां विद्धि त्वमेतं निहितं गुहायाम् ॥ १४॥", tamil_trans: "ப்ர தே ப்ரவீமி தது மே நிபோத ஸ்வர்க்யமக்னிம் நசிகேத: ப்ரஜானன் |\nஅனந்தலோகாப்திம் அதோ ப்ரதிஷ்டாம் வித்தி த்வமேதம் நிஹிதம் குஹாயாம் || 14 ||", english: "Yama said: 'I will teach you the Fire. Know that Fire which leads to infinite worlds and is the support of the universe, and is seated in the cavity of the heart.'", commentary_tamil: "எமன் அக்னி வித்தையை உபதேசிக்கிறார்.", commentary_english: "Yama teaches the Fire." },
            { id: "1.1.15", sanskrit: "लोकादिमग्निं तमुवाच तस्मै या इष्टका यावतीर्वा यथा वा ।\nस चापि तत्प्रत्यवदद्यथोक्तं अथास्य मृत्युः पुनरेवाह तुष्टः ॥ १५॥", tamil_trans: "லோகாதிமக்னிம் தமுவாச தஸ்மை யா இஷ்டகா யாவதீர் வா யதா வா |\nஸ சாபி தத்ப்ரத்யவதத் யதோக்தம் அதாஸ்ய ம்ருத்யு: புனரேவாஹ துஷ்ட: || 15 ||", english: "Yama explained that Fire, the source of worlds, and the bricks required, how many and how arranged. Nachiketa repeated it all correctly. Pleased, Death spoke again.", commentary_tamil: "நசிகேதன் முறையாகக் கற்றான்.", commentary_english: "Nachiketa learns quickly." },
            { id: "1.1.16", sanskrit: "तमब्रवीत्प्रीयमाणो महात्मा वरं तवेहाद्य ददामि भूयः ।\nतवैव नाम्ना भवितायमग्निः सृङ्कां चेमामनेकरूपां गृहाण ॥ १६॥", tamil_trans: "தமப்ரவீத் ப்ரியமாணோ மஹாத்மா வரம் தவேஹாத்ய ததாமி பூய: |\nதவைவ நாம்னா பவிதாயமக்னி: ஸ்ருங்காம் சேமாம் அனேகரூபாம் க்ருஹாண || 16 ||", english: "Pleased, the Great Soul said: 'I give you an extra boon today. This Fire shall be known by your name (Nachiketa Agni). Take also this multi-colored garland.'", commentary_tamil: "இந்த அக்னி இனி 'நசிகேத அக்னி' என்று அழைக்கப்படும்.", commentary_english: "The Fire named after Nachiketa." },
            { id: "1.1.17", sanskrit: "त्रिणाचिकेतस्त्रिभिरेत्य सन्धिं त्रिकर्मकृत्तरति जन्ममृत्यू ।\nब्रह्मजज्ञं देवमीड्यं विदित्वा निचाय्येमाँ शान्तिमत्यन्तमेति ॥ १७॥", tamil_trans: "த்ரிணசிகேஸ் த்ரிபிரேத்ய ஸந்திம் த்ரிகர்மக்ருத் தரதி ஜன்மம்ருத்யூ |\nப்ரஹ்மஜக்ஞம் தேவமீட்யம் விதித்வா நிசாய்யேமாம் ஶாந்திம் அத்யந்தமேதி || 17 ||", english: "He who performs the Nachiketa sacrifice three times, uniting with the three (Vedas/Duties), crosses birth and death. Knowing the Worshipful One (Agni) born of Brahman, he attains supreme peace.", commentary_tamil: "நசிகேத அக்னியை வணங்குபவன் அமைதியை அடைகிறான்.", commentary_english: "Result of the sacrifice." },
            { id: "1.1.18", sanskrit: "त्रिणाचिकेतस्त्रयमेतद्विदित्वा य एवं विद्वाश्चिनुते नाचिकेतम् ।\nस मृत्युपाशान् पुरतः प्रणोद्य शोकातिगो मोदते स्वर्गलोके ॥ १८॥", tamil_trans: "த்ரிணசிகேதஸ் த்ரயமேதத் விதித்வா ய ஏவம் வித்வாம்ஶ்சினுதே நாசிகேதம் |\nஸ ம்ருத்யுபாஶான் புரத: ப்ரணோத்ய ஶோகாதிகோ மோததே ஸ்வர்கலோகே || 18 ||", english: "Knowing these three, he who builds the Nachiketa fire throws off the chains of death and rejoices in Heaven.", commentary_tamil: "மரணத்தை வென்று சொர்க்கத்தை அடைவான்.", commentary_english: "Victory over death." },
            { id: "1.1.19", sanskrit: "एष तेऽग्निर्नचिकेतः स्वर्ग्यो यमवृणीथा द्वितीयेन वरेण ।\nएतमग्निं तवैव प्रवक्ष्यन्ति जनासः तृतीयं वरं नचिकेतो वृणीष्व ॥ १९॥", tamil_trans: "ஏஷ தே'க்னிர் நசிகேத: ஸ்வர்க்யோ யமவ்ருணீதா த்விதீயேன வரேண |\nஏதமக்னிம் தவைவ ப்ரவக்ஷ்யந்தி ஜனாஸ: த்ருதீயம் வரம் நசிகேதோ வ்ருணீஷ்வ || 19 ||", english: "This is your Fire, O Nachiketa, which leads to Heaven. People will call it by your name. Now, choose the third boon.'", commentary_tamil: "மூன்றாவது வரத்தைக் கேள்.", commentary_english: "Ask the Third Boon." },
            { id: "1.1.20", sanskrit: "येयं प्रेते विचिकित्सा मनुष्येऽस्तीत्येके नायमस्तीति चैके ।\nएतद्विद्यामनुशिष्टस्त्वयाहं वराणामेष वरस्तृतीयः ॥ २०॥", tamil_trans: "யேயம் ப்ரேதே விசிகித்ஸா மனுஷ்யே அஸ்தீத்யேகே நாயமஸ்தீதி சைகே |\nஏதத் வித்யாம் அனுஷிஷ்டஸ் த்வயா அஹம் வராணாம் ஏஷ வரஸ் த்ருதீய: || 20 ||", english: "Nachiketa said: 'There is this doubt about a man when he is dead: Some say he exists; others say he does not. I wish to be taught by you the truth of this. This is my third boon.'", commentary_tamil: "மூன்றாம் வரம்: மரணத்தின் பின் என்ன நடக்கிறது? ஆத்மா இருக்கிறதா இல்லையா?", commentary_english: "Boon 3: The Mystery of Death." },
            { id: "1.1.21", sanskrit: "देवैरत्रापि विचिकित्सितं पुरा न हि सुविज्ञेयमणुरेष धर्मः ।\nअन्यं वरं नचिकेतो वृणीष्व मा मोपरोत्सीरति मा सृजैनम् ॥ २१॥", tamil_trans: "தேவைரத்ராபி விசிகித்ஸிதம் புரா ந ஹி ஸுவிக்ஞேயம் அணுரேஷ தர்ம: |\nஅன்யம் வரம் நசிகேதோ வ்ருணீஷ்வ மா மோபரோத்ஸீர் அதி மா ஸ்ருஜைனம் || 21 ||", english: "Yama said: 'Even the gods had doubt on this of old. It is not easy to understand; subtle is this truth. Choose another boon, O Nachiketa. Do not press me; release me from this.'", commentary_tamil: "எமன்: தேவர்களுக்கே இதில் சந்தேகம் உண்டு. வேறேதாவது கேள்.", commentary_english: "Yama tests Nachiketa." },
            { id: "1.1.22", sanskrit: "देवैरत्रापि विचिकित्सितं किल त्वं च मृत्यो यन्न सुविज्ञेयमात्थ ।\nवक्ता चास्य त्वाद्र्गन्यो न लभ्यो नान्यो वरस्तुल्य एतस्य कश्चित् ॥ २२॥", tamil_trans: "தேவைரத்ராபி விசிகித்ஸிதம் கில த்வம் ச ம்ருத்யோ யன்ன ஸுவிக்ஞேயமாத்த |\nவக்தா சாஸ்ய த்வாத்ருக் அன்யோ ந லப்யோ நான்யோ வரஸ் துல்ய ஏதஸ்ய கஶ்சித் || 22 ||", english: "Nachiketa said: 'Since even gods had doubt, and you say it is hard to know, and no other teacher like you can be found, I choose no other boon but this.'", commentary_tamil: "உன்னை விட சிறந்த குரு யாரும் இல்லை. எனக்கு இதுவே வேண்டும்.", commentary_english: "Nachiketa insists." },
            { id: "1.1.23", sanskrit: "शतायुषः पुत्रपौत्रान् वृणीष्व बहून् पशून् हस्तिहिरण्यमश्वान् ।\nभूमेर्महदायतनं वृणीष्व स्वयं च जीव शरदो यावदिच्छसि ॥ २३॥", tamil_trans: "ஶதாயுஷ: புத்ரபௌத்ரான் வ்ருணீஷ்வ பஹூன் பஶூன் ஹஸ்திஹிரண்யம் அஶ்வான் |\nபூமேர் மஹதாயதனம் வ்ருணீஷ்வ ஸ்வயம் ச ஜீவ ஶரதோ யாவதிச்சஸி || 23 ||", english: "Yama said: 'Choose sons and grandsons living a hundred years, many cattle, elephants, gold, and horses. Choose a vast empire on earth and live as many years as you wish.'", commentary_tamil: "எமன்: செல்வம், நீண்ட ஆயுள் கேள்.", commentary_english: "Yama offers worldly pleasures." },
            { id: "1.1.24", sanskrit: "एतत्तुल्यं यदि मन्यसे वरं वृणीष्व वित्तं चिरजीविकां च ।\nमहाभूमौ नचिकेतस्त्वमेधि कामां त्वा कामभाजं करोमि ॥ २४॥", tamil_trans: "ஏதத் துல்யம் யதி மன்யஸே வரம் வ்ருணீஷ்வ வித்தம் சிரஜீவிகாம் ச |\nமஹாபூமௌ நசிகேதஸ் த்வமேதி காமாம் த்வா காமபாஜம் கரோமி || 24 ||", english: "Choose wealth and long life. Be a king of the wide earth. I will make you the enjoyer of all desires.'", commentary_tamil: "ஆசைகளைத் தீர்த்துக்கொள்.", commentary_english: "Promise of enjoyment." },
            { id: "1.1.25", sanskrit: "ये ये कामा दुर्लभा मर्त्यलोके सर्वान्कामाँश्छन्दतः प्रार्थयस्व ।\nइमा रामाः सरथाः सतूर्या न हीदृशा लम्भनीया मनुष्यैः ।\nआभिर्मत्प्रत्ताभिः परिचारयस्व नचिकेतो मरणं माऽनुप्राक्षीः ॥ २५॥", tamil_trans: "யே யே காமா துர்லபா மர்த்யலோகே ஸர்வான் காமாம்ஶ் சந்தத: ப்ரார்த்தயஸ்வ |\nஇமா ராமா: ஸரதா: ஸதூர்யா ந ஹீத்ருஶா லம்பனீயா மனுஷ்யை: |\nஆபிர் மத்ப்ரத்தாபி: பரிசாரயஸ்வ நசிகேதோ மரணம் மா'னுப்ராக்ஷீ: || 25 ||", english: "'Whatever desires are hard to attain in the world of mortals, ask for them. Here are celestial maidens with chariots and music. Be served by them. But do not ask about death.'", commentary_tamil: "தேவலோக இன்பங்களைத் தருகிறேன். ஆனால் மரணத்தைப் பற்றி கேட்காதே.", commentary_english: "The ultimate temptation." },
            { id: "1.1.26", sanskrit: "श्वोभावा मर्त्यस्य यदन्तकैतत् सर्वेन्द्रियाणां जरयन्ति तेजः ।\nअपि सर्वं जीवितमल्पमेव तवैव वाहास्तव नृत्यगीते ॥ २६॥", tamil_trans: "ஶ்வோபாவா மர்த்யஸ்ய யதந்தகைதத் ஸர்வேந்த்ரியாணாம் ஜரயந்தி தேஜ: |\nஅபி ஸர்வம் ஜீவிதமல் பமேவ தவைவ வாஹாஸ் தவர் ந்ருத்யகீதே || 26 ||", english: "Nachiketa said: 'These things last only till tomorrow, O Death. They wear out the vigor of the senses. All life is short. Keep your horses, dance, and song for yourself.'", commentary_tamil: "இவையெல்லாம் நிலையற்றது. உனது பரிசுகளை நீயே வைத்துக்கொள்.", commentary_english: "Rejection of worldly pleasures." },
            { id: "1.1.27", sanskrit: "न वित्तेन तर्पणीयौ मनुष्यो लप्स्यामहे वित्तमद्राक्ष्म चेत्त्वा ।\nजीविष्यामो यावदीशिष्यसि त्वं वरस्तु मे करणीयः स एव ॥ २७॥", tamil_trans: "ந வித்தேன தர்ப்பணீயோ மனுஷ்யோ லப்ஸ்யாமஹே வித்தம் அத்ராக்ஷ்ம சேத் த்வா |\nஜீவிஷ்யாமோ யாவதீஶிஷ்யஸி த்வம் வரஸ்து மே கரணீய: ஸ ஏவ || 27 ||", english: "'Man is not satisfied with wealth. Shall we possess wealth when we see you (Death)? We live only as long as you rule. That boon alone is to be chosen by me.'", commentary_tamil: "பணத்தால் மனிதன் திருப்தி அடைவதில்லை. எனக்கு அந்த வரமே வேண்டும்.", commentary_english: "Steadfastness of Nachiketa." },
            { id: "1.1.28", sanskrit: "अजीर्यताममृतानामुपेत्य जीर्यन्मर्त्यः क्वधःस्थः प्रजानन् ।\nअभिध्यायन् वर्णरतिप्रमोदान् अतिदीर्घे जीविते को रमेत ॥ २८॥", tamil_trans: "அஜீர்யதாம் அம்ருதானாம் உபேத்ய ஜீர்யன் மர்த்ய: க்வத:ஸ்த: ப்ரஜானன் |\nஅபித்யாயன் வர்ணரதிப்ரமோதான் அதிதீர்கே ஜீவிதே கோ ரமேத || 28 ||", english: "'Having approached the undecaying immortals, what decaying mortal would delight in a very long life while contemplating the pleasures of beauty and love?'", commentary_tamil: "அழியும் இன்பங்களில் யாருக்கு நாட்டம் இருக்கும்?", commentary_english: "Dispassion (Vairagya)." },
            { id: "1.1.29", sanskrit: "यस्मिन्निदं विचिकित्सन्ति मृत्यो यत्साम्पराये महति ब्रूहि नस्तत् ।\nयोऽयं वरो गूढमनुप्रविष्टो नान्यं तस्मान्नचिकेता वृणीते ॥ २९॥", tamil_trans: "யஸ்மின்னிதம் விசிகித்ஸந்தி ம்ருத்யோ யத் ஸாம்பராயே மஹதி ப்ரூஹி நஸ் தத் |\nயோ'யம் வரோ கூட மனுப்ரவிஷ்டோ நான்யம் தஸ்மான் நசிகேதா வ்ருணீதே || 29 ||", english: "'Tell us that about which they doubt, O Death, what there is in the great Hereafter. Nachiketa chooses no other boon than this which penetrates the mystery.'", commentary_tamil: "மரணத்தின் மர்மத்தை மட்டுமே நான் அறிய விரும்புகிறேன்.", commentary_english: "Final resolve." },

            // --- Chapter 1, Valli 2 ---
            { id: "1.2.1", sanskrit: "अन्यच्छ्रेयोऽन्यदुतैव प्रेयस्ते उभे नानार्थे पुरुषँ सिनीतः ।\nतयोः श्रेय आददानस्य साधु भवति हीयतेऽर्थाद्य उ प्रेयो वृणीते ॥ १॥", tamil_trans: "அன்யச் ச்ரேயோ'ன்யதுதைவ ப்ரேயஸ் தே உபே நானார்த்தே புருஷம் ஸினீத: |\nதயோ: ஶ்ரேய ஆததானஸ்ய ஸாது பவதி ஹீயதே'ர்த்தாத் ய உ ப்ரேயோ வ்ருணீதே || 1 ||", english: "Yama said: 'The Good (Shreya) is one, the Pleasant (Preya) is another. Both bind man to different goals. It is well with him who chooses the Good; he who chooses the Pleasant misses the goal.'", commentary_tamil: "நன்மை வேறு, இன்பம் வேறு. நன்மையை தேர்ந்தெடுப்பவனே சிறப்படைகிறான்.", commentary_english: "Shreya vs Preya (Good vs Pleasant)." },
            { id: "1.2.2", sanskrit: "श्रेयश्च प्रेयश्च मनुष्यमेतः तौ सम्परीत्य विविनक्ति धीरः ।\nश्रेयो हि धीरोऽभिप्रेयसो वृणीते प्रेयो मन्दो योगक्षेमाद्वृणीते ॥ २॥", tamil_trans: "ஶ்ரேயஶ் ச ப்ரேயஶ் ச மனுஷ்யமேத: தௌ ஸம்பரீத்ய விவினக்தி தீர: |\nஶ்ரேயோ ஹி தீரோ'பிப்ரேயஸோ வ்ருணீதே ப்ரேயோ மந்தோ யோகக்ஷேமாத் வ்ருணீதே || 2 ||", english: "Both the Good and the Pleasant approach man. The wise man discriminates between the two and chooses the Good. The dull-witted chooses the Pleasant for the sake of bodily well-being.", commentary_tamil: "அறிவாளி நன்மையை ஏற்கிறான்; அறிவிலி சுகத்தை நாடுகிறான்.", commentary_english: "Discrimination (Viveka)." },
            { id: "1.2.3", sanskrit: "स त्वं प्रियान्प्रियरूपांश्च कामान् अभिध्यायन् नचिकेतोऽत्यस्राक्षीः ।\nनैतां सृङ्कां वित्तमयीमवाप्तो यस्यां मज्जन्ति बहवो मनुष्याः ॥ ३॥", tamil_trans: "ஸ த்வம் ப்ரியான் ப்ரியரூபாம்ஶ் ச காமான் அபித்யாயன் நசிகேதோ'த்யஸ் ராக்ஷீ: |\nநைதாம் ஸ்ருங்காம் வித்தமயீமவாப்தோ யஸ்யாம் மஜ்ஜந்தி பஹவோ மனுஷ்யா: || 3 ||", english: "'You, O Nachiketa, have rejected desires that are pleasant. You have not accepted this chain of wealth in which many men sink.'", commentary_tamil: "நீ செல்வத்தின் மீது ஆசைப்படவில்லை.", commentary_english: "Nachiketa's renunciation verified." },
            { id: "1.2.4", sanskrit: "दूरमेते विपरीते विषूची अविद्या या च विद्येति ज्ञाता ।\nविद्याभीप्सिनं नचिकेतसं मन्ये न त्वा कामा बहवोऽलोलुपन्त ॥ ४॥", tamil_trans: "தூரமேதே விபரீதே விஷூசீ அவித்யா யா ச வித்யேதி க்ஞாதா |\nவித்யாபீப்ஸினம் நசிகேதஸம் மன்யே ந த்வா காமா பஹவோ'லோலுபந்த || 4 ||", english: "Wide apart are these two—Ignorance and Wisdom. I see Nachiketa as a seeker of Wisdom, for many desires did not distract you.", commentary_tamil: "நீ ஞானத்தை தேடுகிறாய், இன்பத்தை அல்ல.", commentary_english: "Seeker of Wisdom." },
            { id: "1.2.5", sanskrit: "अविद्यायामन्तरे वर्तमानाः स्वयं धीराः पण्डितं मन्यमानाः ।\nदन्द्रम्यमाणाः परियन्ति मूढा अन्धेनैव नीयमाना यथान्धाः ॥ ५॥", tamil_trans: "அவித்யாயாம் அந்தரே வர்தமானா: ஸ்வயம் தீரா: பண்டிதம் மன்யமானா: |\nதந்த்ரம்யமாணா: பரியந்தி மூடா அந்தேனைவ நீயமானா யதாந்தா: || 5 ||", english: "Living in the midst of ignorance, thinking themselves wise, fools go round and round like blind men led by the blind.", commentary_tamil: "குருடனுக்கு வழி காட்டும் குருடனைப் போல.", commentary_english: "Blind leading the blind." },
            { id: "1.2.7", sanskrit: "श्रवणायापि बहुभिर्यो न लभ्यः शृण्वन्तोऽपि बहवो यं न विद्युः ।\nआश्चर्यो वक्ता कुशलोऽस्य लब्धा आश्चर्यो ज्ञाता कुशलानुशिष्टः ॥ ७॥", tamil_trans: "ஶ்ரவணாயாபி பஹுபிர் யோ ந லப்ய: ஶ்ருண்வந்தோ'பி பஹவோ யம் ந வித்யு: |\nஆஶ்சர்யோ வக்தா குஶலோ'ஸ்ய லப்தா ஆஶ்சர்யோ க்ஞாதா குஶலானுஷிஷ்ட: || 7 ||", english: "Many do not hear of the Self; many hear but do not understand. Wonderful is the teacher, rare the student who attains It.", commentary_tamil: "ஆத்மாவை அறிபவர் மிக அரிது.", commentary_english: "Rarity of Self-knowledge." },
            { id: "1.2.14", sanskrit: "अन्यत्र धर्मादन्यत्राधर्मात् अन्यत्रास्मात्कृताकृतात् ।\nअन्यत्र भूताच्च भव्याच्च यत्तत्पश्यसि तद्वद ॥ १४॥", tamil_trans: "அன்யத்ர தர்மாத் அன்யத்ர அதர்மாத் அன்யத்ராஸ்மாத் க்ருதாக்ருதாத் |\nஅன்யத்ர பூதாச்ச பவ்யாச்ச யத் தத் பச்யஸி தத் வத || 14 ||", english: "Nachiketa: 'Tell me that which is beyond Dharma and Adharma, beyond cause and effect, beyond past and future.'", commentary_tamil: "தர்மத்திற்கும் அதர்மத்திற்கும் அப்பாற்பட்டதை சொல்.", commentary_english: "Define the Absolute." },
            { id: "1.2.15", sanskrit: "सर्वे वेदा यत्पदमामनन्ति तपांसि सर्वाणि च यद्वदन्ति ।\nयदिच्छन्तो ब्रह्मचर्यं चरन्ति तत्ते पदँ सङ्ग्रहेण ब्रवीम्योमित्येतत् ॥ १५॥", tamil_trans: "ஸர்வே வேதா யத் பதம் ஆமனந்தி தபாம்ஸி ஸர்வாணி ச யத் வதந்தி |\nயதிச்சந்தோ ப்ரஹ்மசர்யம் சரந்தி தத் தே பதம் ஸங்க்ரஹேண ப்ரவீமி ஓமித்யேதத் || 15 ||", english: "Yama: 'The goal which all Vedas declare, which all austerities aim at, and for which men lead the life of celibacy—I tell you briefly: It is OM.'", commentary_tamil: "அந்த பதம் 'ஓம்'.", commentary_english: "OM is the Supreme Goal." },
            { id: "1.2.16", sanskrit: "एतद्ध्येवाक्षरं ब्रह्म एतद्ध्येवाक्षरं परम् ।\nएतद्ध्येवाक्षरं ज्ञात्वा यो यदिच्छति तस्य तत् ॥ १६॥", tamil_trans: "ஏதத் த்யேவாக்ஷரம் ப்ரஹ்ம ஏதத் த்யேவாக்ஷரம் பரம் |\nஏதத் த்யேவாக்ஷரம் க்ஞாத்வா யோ யதிச்சதி தஸ்ய தத் || 16 ||", english: "This Syllable (Om) is Brahman. This is the Supreme. Knowing this, whatever one desires is his.", commentary_tamil: "ஓம் என்பதை அறிவதே பிரம்மத்தை அறிவது.", commentary_english: "Power of Om." },
            { id: "1.2.18", sanskrit: "न जायते म्रियते वा विपश्चिन् नायं कुतश्चिन्न बभूव कश्चित् ।\nअजो नित्यः शाश्वतोऽयं पुराणो न हन्यते हन्यमाने शरीरे ॥ १८॥", tamil_trans: "ந ஜாயதே ம்ரியதே வா விபஶ்சின் நாயம் குதஶ்சின் ந பபூவ கஶ்சித் |\nஅஜோ நித்ய: ஶாஶ்வதோ'யம் புராணோ ந ஹன்யதே ஹன்யமானே ஶரீரே || 18 ||", english: "The knowing Self is never born; It never dies. It has not come from anything. It is unborn, eternal, everlasting, and primeval. It is not killed when the body is killed.", commentary_tamil: "ஆத்மா பிறப்பதில்லை, இறப்பதில்லை.", commentary_english: "Immortality of the Self." },
            { id: "1.2.20", sanskrit: "अणोरणीयान्महतो महीयान् आत्मास्य जन्तोर्निहितो गुहायाम् ।\nतमक्रतुः पश्यति वीतशोको धातुप्रसादान्महिमानमात्मनः ॥ २०॥", tamil_trans: "அணோரணீயான் மஹதோ மஹீயான் ஆத்மாஸ்ய ஜந்தோஸ் நிஹிதோ குஹாயாம் |\nதமக்ரது: பச்யதி வீதஶோகோ தாதுப்ரஸாதான் மஹிமானம் ஆத்மன: || 20 ||", english: "Subtler than the subtle, greater than the great, the Atman is seated in the heart of the creature. One who is free from desire sees the glory of the Self through tranquility of the senses and becomes free from sorrow.", commentary_tamil: "ஆத்மா அணுவை விட சிறியது, பெரியதை விட பெரியது.", commentary_english: "Smallest of small, Biggest of big." },
            { id: "1.2.23", sanskrit: "नायमात्मा प्रवचनेन लभ्यो न मेधया न बहुना श्रुतेन ।\nयमेवैष वृणुते तेन लभ्यः तस्यैष आत्मा विवृणुते तनूँ स्वाम् ॥ २३॥", tamil_trans: "னாயமாத்மா ப்ரவசனேன லப்யோ ந மேதயா ந பஹுனா ஶ்ருதேன |\nயமேவைஷ வ்ருணுதே தேன லப்ய: தஸ்யைஷ ஆத்மா விவ்ருணுதே தனூம் ஸ்வாம் || 23 ||", english: "This Self cannot be attained by instruction, nor by intellect, nor by much hearing. It is attained only by him whom It chooses. To him the Self reveals Its true nature.", commentary_tamil: "அருளாலேயே இறைவனை அறிய முடியும், அறிவால் அல்ல.", commentary_english: "Grace is essential." },

            // --- Chapter 1, Valli 3 (The Chariot Analogy) ---
            { id: "1.3.3", sanskrit: "आत्मानँ रथिनं विद्धि शरीरँ रथमेव तु ।\nबुद्धिं तु सारथिं विद्धि मनः प्रग्रहमेव च ॥ ३॥", tamil_trans: "ஆத்மானம் ரதினம் வித்தி ஶரீரம் ரதமேவ து |\nபுத்திம் து ஸாரதிம் வித்தி மன: ப்ரக்ரஹமேவ ச || 3 ||", english: "Know the Atman as the Lord of the Chariot, the Body as the Chariot, the Intellect (Buddhi) as the Charioteer, and the Mind as the Reins.", commentary_tamil: "உடல் தேர், ஆத்மா பயணி, புத்தி சாரதி, மனம் கடிவாளம்.", commentary_english: "The Chariot Analogy." },
            { id: "1.3.4", sanskrit: "इन्द्रियाणि हयानाहुर्विषयाँस्तेषु गोचरान् ।\nआत्मेन्द्रियमनोयुक्तं भोक्तेत्याहुर्मनीषिणः ॥ ४॥", tamil_trans: "இந்த்ரியாணி ஹயானாஹுர் விஷ யாம்ஸ்தேஷு கோசரான |\nஆத்மேந்த்ரிய மனோயுக்தம் போக்தேத் யாஹுர் மனீஷிண: || 4 ||", english: "The Senses are the Horses, the Sense Objects are the Paths. The wise call the Atman united with body, senses, and mind the 'Enjoyer'.", commentary_tamil: "புலன்களே குதிரைகள். விஷயங்களே பாதை.", commentary_english: "Senses are horses." },
            { id: "1.3.10", sanskrit: "इन्द्रियेभ्यः परा ह्यर्था अर्थेभ्यश्च परं मनः ।\nमनसस्तु परा बुद्धिर्बुद्धेरात्मा महान्परः ॥ १०॥", tamil_trans: "இந்த்ரியேப்ய: பரா ஹ்யர்த்தா அர்த்தேப்யஶ் ச பரம் மன: |\nமனஸஸ்து பரா புத்திர் புத்தேராத்மா மஹான் பர: || 10 ||", english: "Beyond the senses are the objects; beyond objects is the mind; beyond the mind is the intellect; beyond the intellect is the Great Atman.", commentary_tamil: "புலன்களை விட மனம் உயர்ந்தது, மனதை விட புத்தி உயர்ந்தது.", commentary_english: "Hierarchy of existence." },
            { id: "1.3.14", sanskrit: "उत्तिष्ठत जाग्रत प्राप्य वरान्निबोधत ।\nक्षुरस्य धारा निशिता दुरत्यया दुर्गं पथस्तत्कवयो वदन्ति ॥ १४॥", tamil_trans: "உத்திஷ்டத ஜாக்ரத ப்ராப்ய வரான் நிபோதத |\nக்ஷுரஸ்ய தாரா நிஶிதா துரத்யயா துர்கம் பதஸ் தத் கவயோ வதந்தி || 14 ||", english: "Arise! Awake! Approach the great ones and learn. Like the sharp edge of a razor is that path, difficult to cross and hard to tread - so say the wise.", commentary_tamil: "எழுமின், விழிமின்! ஞானிகளை அணுகி அறிவீராக.", commentary_english: "Arise, Awake!" },

            // --- Chapter 2, Valli 1 ---
            { id: "2.1.1", sanskrit: "पराञ्चि खानि व्यतृणत्स्वयम्भूः तस्मात्पराङ्पश्यति नान्तरात्मन् ।\nकश्चिद्धीरः प्रत्यगात्मानमैक्षत आवृत्तचक्षुरमृतत्वमिच्छन् ॥ १॥", tamil_trans: "பராஞ்சி கானி வ்யத்ருணத் ஸ்வயம்பூ: தஸ்மாத் பராங் பச்யதி நாந்தராத்மன் |\nகஶ்சித் தீர: ப்ரத்யகாத்மானம் ஐக்ஷத ஆவ்ருத்த சக்ஷுர் அம்ருதத்வம் இச்சன் || 1 ||", english: "The Self-Existent Lord pierced the senses outward; therefore one looks outward, not within. Some wise man, seeking immortality, turned his eyes inward and saw the Self.", commentary_tamil: "புலன்கள் வெளியுலகை பார்க்கின்றன. ஞானி உள்ளே பார்க்கிறான்.", commentary_english: "Turn the gaze inward." },
            { id: "2.1.12", sanskrit: "अङ्गुष्ठमात्रः पुरुषो मध्य आत्मनि तिष्ठति ।\nईशानो भूतभव्यस्य न ततो विजुगुप्सते । एतद्वै तत् ॥ १२॥", tamil_trans: "அங்குஷ்டமாத்ர: புருஷோ மத்ய ஆத்மனி திஷ்டதி |\nஈஶானோ பூதபவ்யஸ்ய ந ததோ விஜுகுப்ஸதே | ஏதத் வை தத் || 12 ||", english: "The Person (Purusha), of the size of a thumb, resides in the middle of the body. He is the Lord of the past and future. Knowing Him, one fears no more. This is That.", commentary_tamil: "அங்குஷ்ட அளவுள்ள புருஷன் இதயத்தில் வசிக்கிறான்.", commentary_english: "Purusha size of a thumb." },

            // --- Chapter 2, Valli 2 ---
            { id: "2.2.1", sanskrit: "पुरमेकादशद्वारमजस्यावक्रचेतसः ।\nअनुष्ठाय न शोचति विमुक्तश्च विमुच्यते । एतद्वै तत् ॥ १॥", tamil_trans: "புரமேகாதஶ த்வாரம் அஜஸ்யாவக்ர சேதஸ: |\nஅனுஷ்டாய ந ஶோசதி விமுக்தஶ் ச விமுச்யதே | ஏதத் வை தத் || 1 ||", english: "There is a city of eleven gates (the body) belonging to the Unborn Consciousness. Ruling it, He does not grieve and is liberated. This is That.", commentary_tamil: "உடல் 11 வாசல்களைக் கொண்ட நகரம்.", commentary_english: "City of 11 Gates." },
            { id: "2.2.9", sanskrit: "अग्निर्यथैको भुवनं प्रविष्टो रूपं रूपं प्रतिरूपो बभूव ।\nएकस्तथा सर्वभूतान्तरात्मा रूपं रूपं प्रतिरूपो बहिश्च ॥ ९॥", tamil_trans: "அக்னிர் யதைகோ புவனம் ப்ரவிஷ்டோ ரூபம் ரூபம் ப்ரதிரூபோ பபூவ |\nஏகஸ் ததா ஸர்வபூதாந்தராத்மா ரூபம் ரூபம் ப்ரதிரூபோ பஹிஶ் ச || 9 ||", english: "Just as fire, though one, having entered the world, assumes various forms meant for different objects, so does the one Self within all beings assume various forms.", commentary_tamil: "ஒரே அக்னி பல ரூபங்களில் தெரிவது போல.", commentary_english: "Unity in Diversity." },

            // --- Chapter 2, Valli 3 ---
            { id: "2.3.1", sanskrit: "ऊर्ध्वमूलोऽवाक्शाख एषोऽश्वत्थः सनातनः ।\nतदेव शुक्रं तद्ब्रह्म तदेवामृतमुच्यते ॥ १॥", tamil_trans: "ஊர்த்வமூலோ'வாக்ஶாக ஏஷோ'ஶ்வத்த: ஸனாதன: |\nததேவ ஶுக்ரம் தத் ப்ரஹ்ம ததேவாம்ருத முச்யதே || 1 ||", english: "This is the eternal Ashvattha tree with its roots above and branches below. That root is the Pure, that is Brahman, that is Immortal.", commentary_tamil: "வேர் மேலே, கிளைகள் கீழே உள்ள சம்சார மரம்.", commentary_english: "Tree of Samsara." },
            { id: "2.3.16", sanskrit: "शतं चैका च हृदयस्य नाड्यः तासां मूर्धानमभिनिःसृतैका ।\nतयोर्ध्वमायन्नमृतत्वमेति विष्वङ्ङन्या उत्क्रमणे भवन्ति ॥ १६॥", tamil_trans: "ஶதம் சைகா ச ஹ்ருதயஸ்ய நாட்ய: தாஸாம் மூர்தானமபினி:ஸ்ருதைகா |\nதயூர்த்வமாயன் அம்ருதத்வமேதி விஷ்வங்ஙன்யா உத்க்ரமணே பவந்தி || 16 ||", english: "One hundred and one are the nerves of the heart. One of them (Sushumna) leads up to the crown of the head. Going upward by it, one gains immortality.", commentary_tamil: "சுழுமுனை நாடி வழியாக உயிர் பிரிந்தால் மோட்சம்.", commentary_english: "Path of liberation." },
            { id: "2.3.18", sanskrit: "मृत्युप्रोक्तां नाचिकेतोऽथ लब्ध्वा विद्यामेतां योगविधिं च कृत्स्नम् ।\nब्रह्मप्राप्तो विरजोऽभूद्विमृत्युरन्योऽप्येवं यो विदध्यात्ममेव ॥ १८॥", tamil_trans: "ம்ருத்யுப்ரோக்தாம் நசிகேதோ'த லப்த்வா வித்யாமேதாம் யோகவிதிம் ச க்ருத்ஸ்னம் |\nப்ரஹ்மப்ராப்தோ விரஜோ'பூத் விம்ருத்யுர் அன்யோ'ப்யேவம் யோ விதத்யாத்மமேவ || 18 ||", english: "Nachiketa, having received this knowledge and the rules of Yoga from Death, attained Brahman and became free from passion and death. So also will anyone else who knows the Self.", commentary_tamil: "நசிகேதன் பிரம்மத்தை அடைந்தான்.", commentary_english: "Conclusion." }
        ]
    },
    {
        id: "mundaka",
        title: "Mundaka Upanishad (முண்டகோபனிஷத்)",
        subtitle: "Knowledge of the Absolute (Full 64 Verses)",
        shanti_mantra: {
            sanskrit: "ॐ भद्रं कर्णेभिः शृणुयाम देवाः । भद्रं पश्येमाक्षभिर्यजत्राः ।\nस्थिरैरङ्गैस्तुष्टुवांसस्तनूभिः । व्यशेम देवहितं यदायुः ॥\nस्वस्ति न इन्द्रो वृद्धश्रवाः । स्वस्ति नः पूषा विश्ववेदाः ।\nस्वस्ति नस्तार्क्ष्यो अरिष्टनेमिः । स्वस्ति नो बृहस्पतिर्दधातु ॥\nॐ शान्तिः शान्तिः शान्तिः ॥",
            tamil_trans: "ஓம் பத்ரம் கர்ணேபி: ஶ்ருணுயாம தேவா: | பத்ரம் பச்யேமாக்ஷபிர் யஜத்ரா: |\nஸ்திரைர் அங்கைஸ் துஷ்டுவாம்ஸஸ் தனூபி: | வ்யஶேம தேவஹிதம் யதாயு: ||\nஸ்வஸ்தி ந இந்த்ரோ வ்ருத்தஶ்ரவா: | ஸ்வஸ்தி ந: பூஷா விஶ்வவேதா: |\nஸ்வஸ்தி நஸ் தார்க்ஷ்யோ அரிஷ்டநேமி: | ஸ்வஸ்தி நோ ப்ருஹஸ்பதிர் ததாது ||\nஓம் ஶாந்தி: ஶாந்தி: ஶாந்தி: ||",
            english: "Om. May we, O gods, hear with our ears what is auspicious! May we, O worshipful gods, see with our eyes what is good! May we, strong in limbs and body, sing your praise and enjoy the life allotted to us by Prajapati! Om. Peace! Peace! Peace!"
        },
        verses: [
            // --- Mundaka 1, Khanda 1 ---
            { id: "1.1.1", sanskrit: "ॐ ब्रह्मा देवानां प्रथमः संबभूव विश्वस्य कर्ता भुवनस्य गोप्ता ।\nस ब्रह्मविद्यां सर्वविद्याप्रतिष्ठामथर्वाय ज्येष्ठपुत्राय प्राह ॥ १॥", tamil_trans: "ஓம் ப்ரஹ்மா தேவானாம் ப்ரதம: ஸம்பபூவ விஶ்வஸ்ய கர்தா புவனஸ்ய கோப்தா |\nஸ ப்ரஹ்மவித்யாம் ஸர்வவித்யா ப்ரதிஷ்டாம் அதர்வாய ஜ்யேஷ்ட புத்ராய ப்ராஹ || 1 ||", english: "Om. Brahma, the Maker of the universe and the Preserver of the world, was the first among the devas. He told His eldest son Atharva about the Knowledge of Brahman, the foundation of all knowledge." },
            { id: "1.1.2", sanskrit: "अथर्वणे यां प्रवदेत ब्रह्माऽथर्वा तं पुरोवाचाङ्गिरे ब्रह्मविद्याम् ।\nस भारद्वाजाय सत्यवाहाय प्राह भारद्वाजोऽङ्गिरसे परावराम् ॥ २॥", tamil_trans: "அதர்வணே யாம் ப்ரவதேத ப்ரஹ்மா'தர்வா தம் வுரோவாச அங்கிரே ப்ரஹ்மவித்யாம் |\nஸ பாரத்வாஜாய ஸத்யவாஹாய ப்ராஹ பாரத்வாஜோ'ங்கிரஸே பராவராம் || 2 ||", english: "The Knowledge of Brahman about which Brahma told Atharva, Atharva, in olden times, told Angir. Angir taught it to Satyavaha, of the clan of Bharadwaja, and Satyavaha taught it to Angiras, both the higher and the lower vidya." },
            { id: "1.1.3", sanskrit: "शौनको ह वै महाशालोऽङ्गिरसं विधिवदुपसन्नः पप्रच्छ ।\nकस्मिन्नु भगवो विज्ञाते सर्वमिदं विज्ञातं भवतीति ॥ ३॥", tamil_trans: "ஶௌனகோ ஹ வை மஹாஶாலோ'ங்கிரஸம் விதிவதுபஸன்ன: பப்ரச்ச |\nகஸ்மின்னு பகவோ விக்ஞாதே ஸர்வமிதம் விக்ஞாதம் பவதீதி || 3 ||", english: "Saunaka, the great householder, approached Angiras in the proper manner and said: Revered sir, what is that by the knowing of which all this becomes known?" },
            { id: "1.1.4", sanskrit: "तस्मै स होवाच । द्वे विद्ये वेदितव्ये इति ह स्म यद्ब्रह्मविदो वदन्ति परा चैवापरा च ॥ ४॥", tamil_trans: "தஸ்மை ஸ ஹோவாச | த்வே வித்யே வேதிதவ்யே இதி ஹ ஸ்ம யத் ப்ரஹ்மவிதோ வதந்தி பரா சைவாபரா ச || 4 ||", english: "To him he said: Two kinds of knowledge must be known, this is what all who know Brahman tell us: the Higher Knowledge and the Lower Knowledge." },
            { id: "1.1.5", sanskrit: "तत्रापरा ऋग्वेदो यजुर्वेदः सामवेदोऽथर्ववेदः शिक्षा कल्पो व्याकरणं निरुक्तं छन्दो ज्योतिषमिति ।\nअथ परा यया तदक्षरमधिगम्यते ॥ ५॥", tamil_trans: "தத்ராபரா ருக்வேதோ யஜுர்வேத: ஸாமவேதோ'தர்வவேத: ஶிக்ஷா கல்ப: வ்யாகரணம் நிருக்தம் சந்தோ ஜ்யோதிஷமிதி |\nஅத பரா யயா ததக்ஷரம் அதிகம்யதே || 5 ||", english: "Of these, the Lower Knowledge is the Rig-Veda, the Yaju-Veda, the Sama-Veda, the Atharva-Veda, the Siksha (phonetics), Kalpa (rituals), Vyakarana (grammar), Nirukta (etymology), Chhandas (metre), and Jyotisha (astronomy); but the Higher Knowledge is that by which the Indestructible Brahman is attained." },
            { id: "1.1.6", sanskrit: "यत्तदद्रेश्यमग्राह्यमगोत्रमवर्णमचक्षुःश्रोत्रं तदपाणिपादम् ।\nनित्यं विभुं सर्वगतं सुसूक्ष्मं तदव्ययं यद्भूतयोनिं परिपश्यन्ति धीराः ॥ ६॥", tamil_trans: "யத் தத் அத்ரேஶ்யம் அக்ராஹ்யம் அகோத்ரம் அவர்ணம் அசக்ஷு: ஶ்ரோத்ரம் தத் அபாணிபாதம் |\nநித்யம் விபும் ஸர்வகதம் ஸுஸூக்ஷ்மம் தத் அவ்யயம் யத் பூதியோனிம் பரிபஶ்யந்தி தீரா: || 6 ||", english: "That which cannot be seen, which cannot be seized, which has no origin and no attributes, no eyes and no ears, no hands and no feet; That which is eternal, diversely arising, all-pervading, extremely subtle, and undecaying, which the wise perceive as the Source of all beings." },
            { id: "1.1.7", sanskrit: "यथोर्णनाभिः सृजते गृह्णते च यथा पृथिव्यामोषधयः संभवन्ति ।\nयथा सतः पुरुषात्केशलोमानि तथाऽक्षरात्संभवतीह विश्वम् ॥ ७॥", tamil_trans: "யதோர்ணநாபி: ஸ்ருஜதே க்ருஹ்ணதே ச யதா ப்ருதிவ்யாம் ஓஷதய: ஸம்பவந்தி |\nயதா ஸத: புருஷாத் கேஶலோமானி ததா'க்ஷராத் ஸம்பவதீஹ விஶ்வம் || 7 ||", english: "As the spider sends forth and draws back its thread, as herbs grow on the earth, as the hair grows on the head and body of a living person, so from the Imperishable Universe arises here." },
            { id: "1.1.8", sanskrit: "तपसा चीयते ब्रह्म ततोऽन्नमभिजायते ।\nअन्नात्प्राणो मनः सत्यं लोकाः कर्मसु चामृतम् ॥ ८॥", tamil_trans: "தபஸா சீயதே ப்ரஹ்ம ததோ'ன்னம் அபிஜாயதே |\nஅன்னாத் ப்ராணோ மன: ஸத்யம் லோகா: கர்மஸு சாம்ருதம் || 8 ||", english: "Through brooding Brahman swells (with the joy of creation). From Him arises food; from food, Prana, the mind, the Bhutas, the worlds, and the immortality that rests in actions (karma)." },
            { id: "1.1.9", sanskrit: "यः सर्वज्ञः सर्वविद्यस्य ज्ञानमयं तपः ।\nतस्मादेतद्ब्रह्म नाम रूपमन्नं च जायते ॥ ९॥", tamil_trans: "ய: ஸர்வக்ஞ: ஸர்வவித் யஸ்ய க்ஞானமயம் தப: |\nதஸ்மாத் ஏதத் ப்ரஹ்ம நாம ரூபம் அன்னம் ச ஜாயதே || 9 ||", english: "From Him who knows all and understands all, whose brooding consists of Knowledge, from Him is born this Brahma (Hiranyagarbha), name, form, and food." },

            // --- Mundaka 1, Khanda 2 ---
            { id: "1.2.1", sanskrit: "तदेतत्सत्यं मन्त्रेषु कर्माणि कवयो यान्यपश्यंस्तानि त्रेतायां बहुधा संततानि ।\nतान्याचरथ नियतं सत्यकामा एष वः पन्थाः सुकृतस्य लोके ॥ १॥", tamil_trans: "ததேதத் ஸத்யம் மந்த்ரேஷு கர்மாணி கவய: யான்யபஶ்யம்ஸ் தானி த்ரேதாயாம் பஹுதா ஸந்ததானி |\nதான்யாசரத நியதம் ஸத்யகாமா ஏஷ வ: பந்தா: ஸுக்ருதஸ்ய லோகே || 1 ||", english: "This is the Truth: The sacrificial works which the rishis saw in the mantras (Vedas) were performed in many ways in the Treta Yuga. Practice them always, O you who are desirous of the true fruits of action; this is the path that leads to the worlds of good deeds." },
            { id: "1.2.2", sanskrit: "यदा लेलायते ह्यर्चिः समिद्धे हव्यवाहने ।\nतदाऽऽज्यभागावन्तरेणाऽऽहुतीः प्रतिपादयेत् ॥ २॥", tamil_trans: "யதா லேலாயதே ஹ்யர்ச்சி: ஸமித்தே ஹவ்யவாஹனே |\nததா'ஜ்யபாகா வந்தரேணா'ஹுதீ: ப்ரதிபாதயேத் || 2 ||", english: "When the flame moves, after the fire has been well kindled, then one should pour with faith his oblations between the two portions of melted butter." },
            { id: "1.2.3", sanskrit: "यस्याग्निहोत्रमदर्शमपौर्णमासमचातुर्मास्यमनाग्रयणमतिथिवर्जितं च ।\nअहुतमवैश्वदेवमविधिना हुतमासप्तमांस्तस्य लोकान् हिनस्ति ॥ ३॥", tamil_trans: "யஸ்யாக்னிஹோத்ரம் அதர்ஶம் அபௌர்ணமாஸம் அசாதுர்மாஸ்யம் அநாக்ரயணம் அதிதிவர்ஜிதம் ச |\nஅஹுதம் அவைஶ்வதேவம் அவிதினா ஹுதம் ஆஸப்தமாம்ஸ் தஸ்ய லோகான் ஹினஸ்தி || 3 ||", english: "If a man's Agnihotra sacrifice is not accompanied by the Darsa and the Paurnamasa sacrifices, by the Four Months' sacrifices and the Agrayana sacrifice; if it is unattended by guests or is without offering or is without the worship of All-Gods or is performed contrary to rule - it destroys his seven worlds." },
            { id: "1.2.4", sanskrit: "काली कराली च मनोजवा च सुलोहिता या च सुधूम्रवर्णा ।\nस्फुलिङ्गिनी विश्वरुची च देवी लेलायमाना इति सप्त जिह्वाः ॥ ४॥", tamil_trans: "காலீ கராலீ ச மனோஜவா ச ஸுலோஹிதா யா ச ஸுதூம்ரவர்ணா |\nஸ்புலிங்கினீ விஶ்வருசீ ச தேவீ லேலாயமானா இதி ஸப்த ஜிஹ்வா: || 4 ||", english: "Kali, Karali, Manojava, Sulohita, Sudhumravarna, Sphulingini, and the luminous Visvaruchi - these are the seven moving tongues of fire." },
            { id: "1.2.5", sanskrit: "एतेषु यश्चरते भ्राजमानेषु यथाकालं चाहुतयो ह्याददायन् ।\nतं नयन्त्येताः सूर्यस्य रश्मयो यत्र देवानां पतिरेकोऽधिवासः ॥ ५॥", tamil_trans: "ஏதேஷு யஶ்சரதே ப்ராஜமானேஷு யதாகாலம் சாஹுதயோ ஹ்யாததாயன் |\nதம் நயந்த்யேதா: ஸூர்யஸ்ய ரஶ்மயோ யத்ர தேவானாம் படிரேகோ'திவாஸ: || 5 ||", english: "He who performs rites at the proper time, into these shining flames, is carried by the oblations, which becomes solar rays, to where the one Lord of the Devas presides." },
            { id: "1.2.6", sanskrit: "एह्येहीति तमाहुतयः सुवर्चसः सूर्यस्य रश्मिभिर्यजमानं वहन्ति ।\nप्रियां वाचमभिवदन्त्योऽर्चयन्त्य एष वः पुण्यः सुकृतो ब्रह्मलोकः ॥ ५॥", tamil_trans: "ஏஹ்யேஹீதி தமாஹுதய: ஸுவர்சஸ: ஸூர்யஸ்ய ரஶ்மிபிர் யஜமானம் வஹந்தி |\nப்ரியாம் வாசமபிவதந்த்யோ'ர்ச்சயந்த்ய ஏஷ வ: புண்ய: ஸுக்ருதோ ப்ரஹ்மலோக: || 6 ||", english: "The radiant oblations carry the sacrificer by the rays of the sun, welcoming him with pleasant words, praising him, saying: 'This is the holy Brahma-world, ill-earned by your good deeds.'" },
            { id: "1.2.7", sanskrit: "प्लवा ह्येते अदृढा यज्ञरूपा अष्टादशोक्तमवरं येषु कर्म ।\nएतच्छ्रेयो येऽभिनन्दन्ति मूढा जरामृत्युं ते पुनरेवापि यन्ति ॥ ७॥", tamil_trans: "ப்லவா ஹ்யேதே அத்ருடா யக்ஞரூபா அஷ்டாதஶோக்தம் அவரம் யேஷு கர்ம |\nஏதச்ச்ரேயோ யே'பினந்தந்தி மூடா ஜராம்ருத்யும் தே புனரேவாபி யந்தி || 7 ||", english: "Unsafe are the boats of these eighteen sacrificial forms, in which are expressed the lower work. The fools who approve them as the highest good fall again and again into the domain of old age and death." },
            { id: "1.2.8", sanskrit: "अविद्यायामन्तरे वर्तमानाः स्वयं धीराः पण्डितंमन्यमानाः ।\nजङ्घन्यमानाः परियन्ति मूढा अन्धेनैव नीयमाना यथान्धाः ॥ ८॥", tamil_trans: "அவித்யாயாம் அந்தரே வர்தமானா: ஸ்வயம் தீரா: பண்டிதம்மன்யமானா: |\nஜங்கன்யமானா: பரியந்தி மூடா அந்தேனைவ நீயமானா யதாந்தா: || 8 ||", english: "Living in the midst of ignorance, and thinking themselves wise and learned, the fools go wandering about, afflicted by many troubles, like the blind led by the blind." },
            { id: "1.2.9", sanskrit: "अविद्यायां बहुधा वर्तमाना वयं कृतार्था इत्यभिमन्यन्ति बालाः ।\nयत्कर्मिणो न प्रवेदयन्ति रागात् तेनातुराः क्षीणलोकाश्च्यवन्ते ॥ ९॥", tamil_trans: "அவித்யாயாம் பஹுதா வர்தமானா வயம் க்ருதார்த்தா இத்யபிமன்யந்தி பாலா: |\nயத்கர்மிணோ ந ப்ரவேதயन्ति ராகாத் தேனாதுரா: க்ஷுணலோகா ஶ்ச்யவந்தே || 9 ||", english: "The childish, engrossed in ignorance in various ways, flatter themselves, saying: We have accomplished our aim. Because the performers of Karma do not know the Truth owing to attainment, they fall from heaven, misery-stricken, when the fruit of their work is exhausted." },
            { id: "1.2.10", sanskrit: "इष्टापूर्तं मन्यमाना वरिष्ठं नान्यच्छ्रेयो वेदयन्ते प्रमूढाः ।\nनाकस्य पृष्ठे ते सुकृतेऽनुभूत्वेमं लोकं हीनतरं वा विशन्ति ॥ १०॥", tamil_trans: "இஷ்டாபூர்தம் மன்யமானா வரிஷ்டம் நான்யச் ச்ரேயோ வேதயந்தே ப்ரமூடா: |\nநாகஸ்ய ப்ருஷ்டே தே ஸுக்ருதே'னுபூத்வேமம் லோகம் ஹீனதரம் வா விஶந்தி || 10 ||", english: "The deluded fools, regarding the sacrifices and the humanitarian works as the highest, do not know any higher good. Having enjoyed their reward on the heights of heaven, gained by good works, they enter again this world or a lower one." },
            { id: "1.2.11", sanskrit: "तपःश्रद्धे ये ह्युपवसन्त्यरण्ये शान्ता विद्वांसो भैक्ष्यचर्यां चरन्तः ।\nसूर्यद्वारेण ते विरजाः प्रयान्ति यत्रामृतः स पुरुषो ह्यव्ययात्मा ॥ ११॥", tamil_trans: "தப:ஶ்ரத்தே யே ஹ்யுபவஸந்த்யரண்யே ஶாந்தா வித்வாம்ஸோ பைக்ஷ்யசர்யாம் சரந்த: |\nஸூர்யத்வாரேண தே விரஜா: ப்ரயாந்தி யத்ராம்ருத: ஸ புருஷோ ஹ்யவ்ய யாத்மா || 11 ||", english: "But the wise men of tranquil minds, who live in the forest on alms, practicing penance and devotion, go, freed from impurities, through the gate of the sun to where resides that Immortal Person, the Imperishable Self." },
            { id: "1.2.12", sanskrit: "परीक्ष्य लोकान् कर्मचितान् ब्राह्मणो निर्वेदमायान्नास्त्यकृतः कृतेन ।\nतद्विज्ञानार्थं स गुरुमेवाभिगच्छेत् समित्पाणिः श्रोत्रियं ब्रह्मनिष्ठम् ॥ १२॥", tamil_trans: "பரீக்ஷ்ய லோகான் கர்மசிதான் ப்ராஹ்మణோ நிர்வேதமாயாத் நாஸ்த்யக்ருத: க்ருதேன |\nதத்விக்ஞானார்த்தம் ஸ குருமேவாபிகச்சேத் ஸமித்பாணி: ஶ்ரோத்ரியம் ப்ரஹ்மநிஷ்டம் || 12 ||", english: "Let a brahmana, after having examined all these worlds that are gained by works, acquire freedom from desires: nothing that is eternal can be produced by what is not eternal. In order that he may understand that Eternal, let him, fuel in hand, approach a guru who is well versed in the Vedas and always devoted to Brahman." },
            { id: "1.2.13", sanskrit: "तस्मै स विद्वानुपसन्नाय सम्यक् प्रशान्तचित्ताय शमान्विताय ।\nयेनाक्षरं पुरुषं वेद सत्यं प्रोवाच तां तत्त्वतो ब्रह्मविद्याम् ॥ १३॥", tamil_trans: "தஸ்மை ஸ வித்வானுபஸன்னாய ஸம்யக் ப்ரஶாந்தசித்தாய ஶமான்விதாய |\nயேநாக்ஷரம் புருஷம் வேத ஸத்யம் ப்ரோவாச தாம் தத்வதோ ப்ரஹ்மவித்யாம் || 13 ||", english: "To that pupil who has approached him respectfully, whose mind is altogether tranquil, and whose senses are subdued, the wise teacher truly told that Knowledge of Brahman through which he knows the Imperishable True Person." },

            // --- Mundaka 2, Khanda 1 ---
            { id: "2.1.1", sanskrit: "तदेतत्सत्यं यथा सुदीप्तात् पावकाद्विस्फुलिङ्गाः सहस्रशः प्रभवन्ते सरूपाः ।\nतथाक्षराद्विविधाः सोम्य भावाः प्रजायन्ते तत्र चैवापियन्ति ॥ १॥", tamil_trans: "ததேதத் ஸத்யம் யதா ஸுதீப்தாத் பாவகாத் விஸ்புலிங்கா: ஸஹஸ்ரஶ: ப்ரபவந்தே ஸரூபா: |\nததாக்ஷராத் விவிதா: ஸோம்ய பாவா: ப்ரஜாயந்தே தத்ர சைவாபியந்தி || 1 ||", english: "This is the Truth: As from a blazing fire, sparks essentially akin to it fly forth by the thousand, so also, my good friend, do various beings come forth from the imperishable Brahman and unto Him again return." },
            { id: "2.1.2", sanskrit: "दिव्यो ह्यमूर्तः पुरुषः स बाह्याभ्यन्तरो ह्यजः ।\nअप्राणो ह्यमनाः शुभ्रो ह्यक्षरात् परतः परः ॥ २॥", tamil_trans: "திவ்யோ ஹ்யமூர்த: புருஷ: ஸ பாஹ்யாப்யந்தரோ ஹ்யஜ: |\nஅப்ராணோ ஹ்யமனா: ஶுப்ரோ ஹ்யக்ஷராத் பரத: பர: || 2 ||", english: "He is the self-luminous and formless Purusha, uncreated and existing both within and without. He is devoid of prana, devoid of mind, pure and higher than the supreme Imperishable." },
            { id: "2.1.3", sanskrit: "एतस्माज्जायते प्राणो मनः सर्वेन्द्रियाणि च ।\nखं वायुर्ज्योतिरापः पृथिवी विश्वस्य धारिणी ॥ ३॥", tamil_trans: "ஏதஸ்மாஜ் ஜாயதே ப்ராணோ மன: ஸர்வேந்த்ரியாணி ச |\nகம் வாயூர்ஜ்யோதிராப: ப்ருதிவீ விஶ்வஸ்ய தாரிணீ || 3 ||", english: "From Him are born prana, mind, all the sense-organs, Akasa, air, fire, water and earth, which supports all." },
            { id: "2.1.4", sanskrit: "अग्नीर्मूर्धा चक्षुषी चन्द्रसूर्यौ दिशः श्रोत्रे वाग् विवृताश्च वेदाः ।\nवायुः प्राणो हृदयं विश्वमस्य पद्भ्यां पृथिवी ह्येष सर्वभूतान्तरात्मा ॥ ४॥", tamil_trans: "அக்னிர் மூர்தா சக்ஷுஷீ சந்த்ரஸூர்யௌ திஶ: ஶ்ரோத்ரே வாக் விவ்ருதாஶ்ச வேதா: |\nவாயு: ப்ராணோ ஹ்ருதயம் விஶ்வமஸ்ய பத்ப்யாம் ப்ருதிவீ ஹ்யேஷ ஸர்வபூதாந்தராத்மா || 4 ||", english: "The heavens are His head; the sun and moon, His eyes; the quarters, His ears; the revealed Vedas, His speech; the wind is His breath; the universe, His heart. From his feet is produced the earth. He is, indeed, the inner Self of all beings." },
            { id: "2.1.5", sanskrit: "तस्मादग्निः समिधो यस्य सूर्यः सोमात्पर्जन्य ओषधयः पृथिव्याम् ।\nपुमान् रेतः सिञ्चति योषितायां बह्वीः प्रजाः पुरुषात्सम्प्रसूताः ॥ ५॥", tamil_trans: "தஸ்மாதக்னி: ஸமிதோ யஸ்ய ஸூர்ய: ஸோமாத் பர்ஜன்ய ஓஷதய: ப்ருதிவ்யாம் |\nபுமான் ரேத: ஸிஞ்சதி யோஷிதாயாம் பஹ்வீ: ப்ரஜா: புருஷாத் ஸம்ப்ரஸூதா: || 5 ||", english: "From Him comes the Fire whose fuel is the sun; from the moon comes rain; from rain, the herbs... Thus many living beings are born of the Purusha." },
            { id: "2.1.6", sanskrit: "तस्मादृचः साम यजूंषि दीक्षा यज्ञाश्च सर्वे क्रतवो दक्षिणाश्च ।\nसंवत्सरश्च यजमानश्च लोकाः सोमो यत्र पवते यत्र सूर्यः ॥ ६॥", tamil_trans: "தஸ்மாத் ருச: ஸாம யஜூம்ஷி தீக்ஷா யக்ஞாஶ்ச ஸர்வே க்ரதவோ தக்ஷிணாஶ்ச |\nஸம்வத்ஸரஶ்ச யஜமானஶ்ச லோகா: ஸோமோ யத்ர பவதே யத்ர ஸூர்ய: || 6 ||", english: "From Him have come the Rik, the Saman, the Yajus, the Diksha, all sacrifices... and the worlds which the moon sanctifies and the sun illumines." },
            { id: "2.1.7", sanskrit: "तस्माच्च देवा बहुधा सम्प्रसूताः साध्या मनुष्याः पशवो वयांसि ।\nप्राणापानौ व्रीहियवौ तपश्च श्रद्धा सत्यं ब्रह्मचर्यं विधिश्च ॥ ७॥", tamil_trans: "தஸ்மாச்ச தேவா பஹுதா ஸம்ப்ரஸூதா: ஸாத்யா மனுஷ்யா: பஶவோ வயாம்ஸி |\nப்ராணாபானௌ வ்ரீஹியவௌ தபஶ்ச ஶ்ரத்தா ஸத்யம் ப்ரம்ஹசர்யம் விதிஶ்ச || 7 ||", english: "By Him are begotten the various devas, the sadhyas, men, cattle, birds and also prana and apana, rice and corn, penance, faith, truth, continence and law." },
            { id: "2.1.8", sanskrit: "सप्त प्राणाः प्रभवन्ति तस्मात् सप्तार्चिषः समिधः सप्त होमाः ।\nसप्त इमे लोका येषु चरन्ति प्राणा गुहाशया निहिताः सप्त सप्त ॥ ८॥", tamil_trans: "ஸப்த ப்ராணா: ப்ரபவந்தி தஸ்மாத் ஸப்தார்சிஷ: ஸமித: ஸப்த ஹோமா: |\nஸப்த இமே லோகா யேஷு சரந்தி ப்ராணா குஹாஶயா நிஹிதா: ஸப்த ஸப்த || 8 ||", english: "From Him have sprung the seven pranas, the seven flames, the seven kinds of fuel, the seven oblations and also the seven planes where move the pranas." },
            { id: "2.1.9", sanskrit: "अतः समुद्रा गिरयश्च सर्वेऽस्मात् स्यन्दन्ते सिन्धवः सर्वरूपाः ।\nअतश्च सर्वा ओषधयो रसश्च येनैष भूतैस्तिष्ठते ह्यन्तरात्मा ॥ ९॥", tamil_trans: "அத: ஸமுத்ரா கிரயஶ்ச ஸர்வேஸ்மாத் ஸ்யந்தந்தே ஸிந்தவ: ஸர்வரூபா: |\nஅதஶ்ச ஸர்வா ஓஷதயோ ரஸஶ்ச யேனைஷ பூதைஸ் திஷ்டதே ஹ்யந்தராத்மா || 9 ||", english: "From Him come all the oceans and the mountains; from Him flow rivers of every kind; from Him have come all plants and flavours." },
            { id: "2.1.10", sanskrit: "पुरुष एवेदं विश्वं कर्म तपो ब्रह्म परामृतम् ।\nएतद्यो वेद निहितं गुहायां सोऽविद्याग्रन्थिं विकिरतीह सोम्य ॥ १०॥", tamil_trans: "புருஷ ஏவேதம் விஶ்வம் கர்ம தபோ ப்ரஹ்ம பராம்ருதம் |\nஏதத் யோ வேத நிஹிதம் குஹாயாம் ஸோ'வித்யாக்ரந்திம் விகிரதீஹ ஸோம்ய || 10 ||", english: "The Purusha alone is verily the universe, which consists of work and austerity. He who knows this Brahman hidden in the cave of the heart cuts asunder the knot of ignorance." },

            // --- Mundaka 2, Khanda 2 ---
            { id: "2.2.1", sanskrit: "आविः सन्निहितं गुहाचरं नाम महत्पदमत्रैतत् समर्पितम् ।\nएजत्प्राणन्निमिषच्च यदेतज्जानथ सदसद्वरेण्यं परं विज्ञानाद्यद्वरिष्ठं प्रजानाम् ॥ १॥", tamil_trans: "ஆவி: ஸம்னிஹிதம் குஹாசரம் நாம மஹத் பதம் அத்ரைதத் ஸமர்பிதம் |\nஏஜத் ப்ராணன் நிமிஷச்ச யதேதஜ் ஜானத ஸதஸத் வரேண்யம் பரம் விக்ஞானாத் யத் வரிஷ்டம் ப்ரஜானாம் || 1 ||", english: "The Luminous Brahman dwells in the cave of the heart and is known to move there. It is the great support of all. Know that to be your Self-that which is both gross and subtle, adorable, supreme and beyond understanding." },
            { id: "2.2.2", sanskrit: "यदर्चिमद्यदणुभ्योऽणु च यस्मिँल्लोका निहिता लोकिनश्च ।\nतदेतदक्षरं ब्रह्म स प्राणस्तदु वाङ्मनः तदेतत्सत्यं तदमृतं तद्वेद्धव्यं सोम्य विद्धि ॥ २॥", tamil_trans: "யதர்சிமத் யதணுப்யோணு ச யஸ்மிம் லோகா நிஹிதா லோகினஶ்ச |\nததேதத் அக்ஷரம் ப்ரம்ஹ ஸ ப்ராணஸ் தது வாங்மன: ததேதத் ஸத்யம் தத அம்ருதம் தத் வேத்தவ்யம் ஸோம்ய வித்தி || 2 ||", english: "That which is radiant, subtler than the subtle, That by which all the worlds are supported-That verily is the indestructible Brahman... That alone is to be struck. Strike It, my good friend." },
            { id: "2.2.3", sanskrit: "धनुर्गृहीत्वौपनिषदं महास्त्रं शरं ह्युपासानिशितं सन्धयीत ।\nआयम्य तद्भावगतेन चेतसा लक्ष्यं तदेवाक्षरं सोम्य विद्धि ॥ ३॥", tamil_trans: "தனுர் க்ருஹீத்வௌபநிஷதம் மஹாஸ்த்ரம் ஶரம் ஹ்யுபாஸா நிஶிதம் ஸந்தயீத |\nஆயம்ய தத் பாவகதேன சேதஸா லக்ஷ்யம் ததேவாக்ஷரம் ஸோம்ய வித்தி || 3 ||", english: "Take the Upanishad as the bow, the great weapon and place upon it the arrow sharpened by meditation. Then, having drawn it back with a mind directed to the thought of Brahman, strike that mark - the Imperishable." },
            { id: "2.2.4", sanskrit: "प्रणवो धनुः शरो ह्यात्मा ब्रह्म तल्लक्ष्यमुच्यते ।\nअप्रमत्तेन वेद्धव्यं शरवत् तन्मयो भवेत् ॥ ४॥", tamil_trans: "ப்ரணவோ தனு: ஶரோ ஹ்யாத்மா ப்ரஹ்ம தல்லக்ஷ்ய முச்யதே |\nஅப்ரமத்தேன வேத்தவ்யம் ஶரவத் தன்மயோ பவேத் || 4 ||", english: "Om is the bow; the atman is the arrow; Brahman is said to be the mark. It is to be struck by an undistracted mind. Then the atman becomes one with Brahman, as the arrow with the target." },
            { id: "2.2.5", sanskrit: "यस्मिन् द्यौः पृथिवी चान्तरिक्षमोतं मनः सह प्राणैश्च सर्वैः ।\nतमेवैकं जानथ आत्मानमन्या वाचो विमुञ्चथामृतस्यैष सेतुः ॥ ५॥", tamil_trans: "யஸ்மின் த்யௌ: ப்ருதிவீ சாந்தரிக்ஷமோதம் மன: ஸஹ ப்ராணைஶ்ச ஸர்வை: |\nதமேவைகம் ஜானத ஆத்மானம் அன்யா வாசோ விமுஞ்சத அம்ருதஸ்யைஷ ஸேது: || 5 ||", english: "In Him are woven the heaven, the earth, and the sky... Know Him alone as the one Self. Dismiss other words. This is the bridge to immortality." },
            { id: "2.2.6", sanskrit: "अरा इव रथनाभौ संहता यत्र नाड्यः स एषोऽन्तश्चरते बहुधा जायमानः ।\nओमित्येवं ध्यायथ आत्मानं स्वस्ति वः पाराय तमसः परस्तात् ॥ ६॥", tamil_trans: "அரா இவ ரதநாபௌ ஸம்ஹதா யத்ர நாட்ய: ஸ ஏஷோ'ந்தஶ்சரதே பஹுதா ஜாயமான: |\nஓம் இத்யேவம் த்யாயத ஆத்மானம் ஸ்வஸ்தி வ: பாராய தமஸ: பரஸ்தாத் || 6 ||", english: "He moves about, becoming manifold, within the heart, where the nerves meet like spokes fastened to the nave of a chariot wheel. Meditate on the Atman as OM. Hail to you! May you cross beyond the sea of darkness." },
            { id: "2.2.7", sanskrit: "यः सर्वज्ञः सर्वविद्यस्यैष महिमा भुवि ।\nदिव्ये ब्रह्मपुरे ह्येष व्योम्न्यात्मा प्रतिष्ठितः ॥ ७॥", tamil_trans: "ய: ஸர்வக்ஞ: ஸர்வவித் யஸ்யைஷ மஹிமா புவி |\nதிவ்யே ப்ரஹ்மபுரே ஹ்யேஷ வ்யோம்ன்யாத்மா ப்ரதிஷ்டித: || 7 ||", english: "He who knows all and understands all and to whom belongs all the glory in the world - He, the Atman, is placed in the space in the effulgent abode of Brahman (the heart)." },
            { id: "2.2.8", sanskrit: "भिद्यते हृदयग्रन्थिश्छिद्यन्ते सर्वसंशयाः ।\nक्षीयन्ते चास्य कर्माणि तस्मिन्दृष्टे परावरे ॥ ८॥", tamil_trans: "பித்யதே ஹ்ருதயக்ரந்தி: சித்யந்தே ஸர்வஸம்ஶயா: |\nக்ஷுயந்தே சாஸ்ய கர்மாணி தஸ்மின் த்ருஷ்டே பராவரே || 8 ||", english: "When that Self, which is both high and low, is realized, the knot of the heart gets untied, all doubts are solved, and all actions become dissipated." },
            { id: "2.2.9", sanskrit: "हिरण्मये परे कोशे विरजं ब्रह्म निष्कलम् ।\nतच्छुभ्रं ज्योतिषां ज्योतिस्तद्यदात्मविदो विदुः ॥ ९॥", tamil_trans: "ஹிரண்மயே பரே கோஶே விரஜம் ப்ரஹ்ம நிஷ்கலம் |\nதத் ஶுப்ரம் ஜ்யோதிஷாம் ஜ்யோதிஸ் தத் யத் ஆத்மவிதோ விது: || 9 ||", english: "The stainless, indivisible Brahman, the pure, the Light of lights, is seated in the innermost golden sheath. That is what the knowers of the Atman know." },
            { id: "2.2.10", sanskrit: "न तत्र सूर्यो भाति न चन्द्रतारकं नेमा विद्युतो भान्ति कुतोऽयमग्निः ।\nतमेव भान्तमनुभाति सर्वं तस्य भासा सर्वमिदं विभाति ॥ १०॥", tamil_trans: "ந தத்ர ஸூர்யோ பாதி ந சந்த்ரதாரகம் நேமா வித்யுதோ பாந்தி குதோ'யமக்னி: |\nதமேவ பாந்தமனுபாதி ஸர்வம் தஸ்ய பாஸா ஸர்வமிதம் விபாதி || 10 ||", english: "The sun does not shine there, nor the moon and the stars, nor these lightnings - much less this fire. He shining, everything shines after Him. By His light all this is lighted." },
            { id: "2.2.11", sanskrit: "ब्रह्मैवेदममृतं पुरस्ताद् ब्रह्म पश्चाद् ब्रह्म दक्षिणतश्चोत्तरेण ।\nअधश्चोर्ध्वं च प्रसृतं ब्रह्मैवेदं विश्वमिदं वरिष्ठम् ॥ ११॥", tamil_trans: "ப்ரஹ்மைவேதம் அம்ருதம் புரஸ்தாத் ப்ரஹ்ம பஶ்சாத் ப்ரஹ்ம தக்ஷிணதஶ் சோத்தரேண |\nஅதஶ்ச ஊர்த்வம் ச ப்ரஸ்ருதம் ப்ரஹ்மைவேதம் விஶ்வம் இதம் வரிஷ்டம் || 11 ||", english: "Brahman alone is all this. It is in the front, It is behind, It is on the right, It is on the left. It spreads both above and below. This universe is nothing but Brahman, the Supreme." },

            // --- Mundaka 3, Khanda 1 ---
            { id: "3.1.1", sanskrit: "द्वा सुपर्णा सयुजा सखाया समानं वृक्षं परिषस्वजाते ।\nतयोरन्यः पिप्पलं स्वाद्वत्त्यनश्नन्नन्यो अभिचाकशीति ॥ १॥", tamil_trans: "த்வா ஸுபர்ணா ஸயுஜா ஸகாயா ஸமானம் வ்ருக்ஷம் பரிஷஸ்வஜாதே |\nதயோரன்ய: பிப்பலம் ஸ்வாத்வத் அத்தி அனஶ்னன் அன்யோ அபிசாகஶீதி || 1 ||", english: "Two birds, united always and known by the same name, closely cling to the same tree. One of them eats the sweet fruit; the other looks on without eating." },
            { id: "3.1.2", sanskrit: "समाने वृक्षे पुरुषो निमग्नोऽनीशया शोचति मुह्यमानः ।\nजुष्टं यदा पश्यत्यन्यमीशमस्य महिमानमिति वीतशोकः ॥ २॥", tamil_trans: "ஸமானே வ்ருக்ஷே புருஷோ நிமக்னோ'னீஶயா ஶோசதி முஹ்யமான: |\nஜுஷ்டம் யதா பஶ்யத்யன்ய மீஶமஸ்ய மஹிமான மிதி வீதஶோக: || 2 ||", english: "Seated on the same tree, the Jiva, moaning and bewildered by his impotence, grieves. But when he sees the other, the Lord, worshipped by all, and His glory, he becomes free from grief." },
            { id: "3.1.3", sanskrit: "यदा पश्यः पश्यते रुक्मवर्णं कर्तारमीशं पुरुषं ब्रह्मयोनिम् ।\nतदा विद्वान् पुण्यपापे विधूय निरञ्जनः परमं साम्यमुपैति ॥ ३॥", tamil_trans: "யதா பஶ்ய: பஶ்யதே ருக்மவர்ணம் கர்தாரம் ஈஶம் புருஷம் ப்ரஹ்மயினிம் |\nததா வித்வான் புண்யபாபே விதூய நிரஞ்ஜன: பரமம் ஸாம்யமுபைதி || 3 ||", english: "When the seer beholds the self-luminous Creator, the Lord, the Purusha, the progenitor of Brahma, then he, the wise seer, shakes off good and evil, becomes stainless, and reaches the supreme unity." },
            { id: "3.1.4", sanskrit: "प्राणो ह्येष यः सर्वभूतैर्विभाति विजानन् विद्वान् भवते नातिवादी ।\nआत्मक्रीड आत्मरतिः क्रियावानेष ब्रह्मविदां वरिष्ठः ॥ ४॥", tamil_trans: "ப்ராணோ ஹ்யேஷ ய: ஸர்வபூதைர் விபாதி விஜானன் வித்வான் பவதே நாதிவாதீ |\nஆத்மக்ரீட ஆத்மரதி: க்ரியாவான் ஏஷ ப்ரஹ்மவிதாம் வரிஷ்ட: || 4 ||", english: "He indeed is Prana who shines forth in all beings. Knowing Him, the wise man does not talk of anything else. Sporting in the Self, delighting in the Self, performing action, such a one is the greatest among the knowers of Brahman." },
            { id: "3.1.5", sanskrit: "सत्येन लभ्यस्तपसा ह्येष आत्मा सम्यग्ज्ञानेन ब्रह्मचर्येण नित्यम् ।\nअन्तःशरीरे ज्योतिर्मयो हि शुभ्रो यं पश्यन्ति यतयः क्षीणदोषाः ॥ ५॥", tamil_trans: "ஸத்யேன லப்யஸ் தபஸா ஹ்யேஷ ஆத்மா ஸம்யக் க்ஞானேன ப்ரஹ்மசர்யேண நித்யம் |\nஅந்த:ஶரீரே ஜ்யோதிர்மயோ ஹி ஶுப்ரோ யம் பஶ்யந்தி யதய: க்ஷுணதோஷா: || 5 ||", english: "This Atman is obtained by Truth, by Tapas, by right knowledge, and by a constant life of chastity. He is formed of light and is within the body. The sages, their impurities destroyed, see Him." },
            { id: "3.1.6", sanskrit: "सत्यमेव जयते नानृतं सत्येन पन्था विततो देवयानः ।\nयेनाक्रमन्त्यृषयो ह्याप्तकामा यत्र तत्सत्यस्य परमं निधानम् ॥ ६॥", tamil_trans: "ஸத்யமேவ ஜயதே நான்ருதம் ஸத்யேன பந்தா விததோ தேவயான: |\nயேனாக்ரமந்த் ருஷயோ ஹ்யாப்தகாமா யத்ர தத் ஸத்யஸ்ய பரமம் நிதானம் || 6 ||", english: "Truth alone prevails, not falsehood. By truth the path is laid out, the Way of the Gods, on which the seers, whose every desire is satisfied, proceed to the Highest Abode of the True." },
            { id: "3.1.7", sanskrit: "बृहच्च तद्दिव्यमचिन्त्यरूपं सूक्ष्माच्च तत्सूक्ष्मतरं विभाति ।\nदूरात्सुदूरे तदिहान्तिके च पश्यत्स्विहैव निहितं गुहायाम् ॥ ७॥", tamil_trans: "ப்ருஹச்ச தத் திவ்யம் அசிந்த்யரூபம் ஸூக்ஷ்மாச்ச தத் ஸூக்ஷ்மதரம் விபாதி |\nதூராத் ஸுதூரே தத் இஹாந்திகே ச பஶ்யத்ஸ்விஹைவ நிஹிதம் குஹாயாம் || 7 ||", english: "That (Brahman) shines forth, vast, divine, inconceivable, subtler than the subtle. It is far beyond what is far, and yet here very near at hand. Verily, It is seen here, dwelling in the cave of the heart of conscious beings." },
            { id: "3.1.8", sanskrit: "न चक्षुषा गृह्यते नापि वाचा नान्यैर्देवैस्तपसा कर्मणा वा ।\nज्ञानप्रसादेन विशुद्धसत्त्वस्ततस्तु तं पश्यते निष्कलं ध्यायमानः ॥ ८॥", tamil_trans: "ந சக்ஷுஷா க்ருஹ்யதே நாபி வாசா நான்யைர் தேவைஸ் தபஸா கர்மணா வா |\nக்ஞானப்ரஸாதேன விஶுத்த ஸத்த்வஸ் ததஸ்து தம் பஶ்யதே நிஷ்கலம் த்யாயமான: || 8 ||", english: "He is not grasped by the eye, nor by speech, nor by other senses, nor by penance or good works. When a man's nature has become purified by the serene light of knowledge, then he, meditating, sees Him, who is without parts." },
            { id: "3.1.9", sanskrit: "एषोऽणुरात्मा चेतसा वेदितव्यो यस्मिन्प्राणः पञ्चधा संविवेश ।\nप्राणैश्चित्तं सर्वमोतं प्रजानां यस्मिन्विशुद्धे विभवत्येष आत्मा ॥ ९॥", tamil_trans: "ஏஷோ'ணுர் ஆத்மா சேதஸா வேதிதவ்யோ யஸ்மின் ப்ராண: பஞ்சதா ஸம்விவேஶ |\nப்ராணைஶ் சித்தம் ஸர்வமோதம் ப்ரஜானாம் யஸ்மின் விஶுத்தே விபவத்யேஷ ஆத்மா || 9 ||", english: "The subtle Atman is to be known by the intellect as being in the body, where the Prana has entered in five ways. The whole system of the body is pervaded by Prana. When the mind is purified, the Atman shines forth." },
            { id: "3.1.10", sanskrit: "यं यं लोकं मनसा संविभाति विशुद्धसत्त्वः कामयते यांश्च कामान् ।\nतं तं लोकं जयते तांश्च कामांस्तस्मादात्मज्ञं ह्यर्चयेद्भूतिकामः ॥ १०॥", tamil_trans: "யம் யம் லோகம் மனஸா ஸம்விபாதி விஶுத்தஸத்த்வ: காமயதே யாம்ஶ்ச காமான் |\nதம் தம் லோகம் ஜயதே தாம்ஶ்ச காமான் தஸ்மாத் ஆத்மக்ஞம் ஹ்யர்சயேத் பூதிகாம: || 10 ||", english: "Whatever world a man of pure understanding envisages in his mind and whatever desires he cherishes, that world he conquers and those desires he obtains. Therefore let the man who wants prosperity worship the knower of the Atman." },

            // --- Mundaka 3, Khanda 2 ---
            { id: "3.2.1", sanskrit: "स वेदैतत्परमं ब्रह्म धाम यत्र विश्वं निहितं भाति शुभ्रम् ।\nउपासते पुरुषं ये ह्यकामास्ते शुक्रमेतदतिवर्तन्ति धीराः ॥ १॥", tamil_trans: "ஸ வேதைதத் பரமம் ப்ரஹ்ம தாம யத்ர விஶ்வம் நிஹிதம் பாதி ஶுப்ரம் |\nஉபாஸதே புருஷம் யே ஹ்யகாமாஸ் தே ஶுக்ரம் ஏதத் அதிவர்தந்தி தீரா: || 1 ||", english: "He, the Knower of the Self, knows the Supreme Abode of Brahman, extending in which the universe shines brightly. The wise who, free from desires, worship the Purusha, pass beyond the seed of rebirth." },
            { id: "3.2.2", sanskrit: "कामान् यः कामयते मन्यमानः स कामभिर्जायते तत्र तत्र ।\nपर्याप्तकामस्य कृतात्मनस्तु इहैव सर्वे प्रविलीयन्ति कामाः ॥ २॥", tamil_trans: "காமான் ய: காமயதே மன்யமான: ஸ காமபிர் ஜாயதே தத்ர தத்ர |\nபர்யாப்தகாமஸ்ய க்ருதாத்மனஸ்து இஹைவ ஸர்வே ப்ரவிலீயந்தி காமா: || 2 ||", english: "He who covets desirable things, while brooding on them, is born amidst those desires. But for him whose desires have been fulfilled and who has realized the Atman, all desires vanish even here on earth." },
            { id: "3.2.3", sanskrit: "नायमात्मा प्रवचनेन लभ्यो न मेधया न बहुना श्रुतेन ।\nयमेवैष वृणुते तेन लभ्यस्तस्यैष आत्मा विवृणुते तनूं स्वाम् ॥ ३॥", tamil_trans: "னாயமாத்மா ப்ரவசனேன லப்யோ ந மேதயா ந பஹுனா ஶ்ருதேன |\nயமேவைஷ வ்ருணுதே தேன லப்யஸ் தஸ்யைஷ ஆத்மா விவ்ருணுதே தனூம் ஸ்வாம் || 3 ||", english: "This Atman cannot be attained by instruction, nor by intellect, nor by much hearing. It is attained only by him whom It chooses. To him the Atman reveals Its true nature." },
            { id: "3.2.4", sanskrit: "नायमात्मा बलहीनेन लभ्यो न च प्रमादात्तपसो वाप्यलिङ्गात् ।\nएतैरुपायैर्यतते यस्तु विद्वांस्तस्यैष आत्मा विशते ब्रह्मधाम ॥ ४॥", tamil_trans: "னாயமாத்மா பலஹீனேன லப்யோ ந ச ப்ரமாதாத் தபஸோ வாப்யலிங்காத் |\nஏதைருபாயைர் யததே யஸ்து வித்வாம்ஸ் தஸ்யைஷ ஆத்மா விஶதே ப்ரஹ்மதாம || 4 ||", english: "This Atman cannot be attained by one who is without strength or distraction or by tapas without a mark (renunciation). But if a wise man strives by these means, his self enters the Abode of Brahman." },
            { id: "3.2.5", sanskrit: "संप्राप्यैनमृषयो ज्ञानतृप्ताः कृतात्मानो वीतरागाः प्रशान्ताः ।\nते सर्वगं सर्वतः प्राप्य धीरा युक्तात्मानः सर्वमेवाविशन्ति ॥ ५॥", tamil_trans: "ஸம்ப்ராப்யைனம் ருஷயோ க்ஞானத்ருப்தா: க்ருதாத்மனோ வீதராகா: ப்ரஶாந்தா: |\nதே ஸர்வகம் ஸர்வத: ப்ராப்ய தீரா யுக்தாத்மான: ஸர்வமேவா விஶந்தி || 5 ||", english: "Having attained Him, the seers become satisfied with their Knowledge, their purpose fulfilled, their passions gone, and their minds tranquil. The wise, having reached the Omnipresent One on all sides, enter into the All." },
            { id: "3.2.6", sanskrit: "वेदान्तविज्ञानसुनिश्चितार्थाः संन्यासयोगाद्यतयः शुद्धसत्त्वाः ।\nते ब्रह्मलोकेषु परान्तकाले परामृताः परिमुच्यन्ति सर्वे ॥ ६॥", tamil_trans: "வேதாந்த விக்ஞான ஸுனிஸ்சிதர்த்தா: ஸன்யாஸயோகாத் யதய: ஶுத்தஸத்த்வா: |\nதே ப்ரஹ்மலோகேஷு பராந்தகாலே பராம்ருதா: பரிமுச்யந்தி ஸர்வே || 6 ||", english: "The Seers, who have ascertained the meaning of the Vedanta knowledge, and who have purified their natures through the yoga of renunciation, are all liberated, on the final dissolution, in the World of Brahman, and become one with the Absolute." },
            { id: "3.2.7", sanskrit: "गताः कलाः पञ्चदश प्रतिष्ठा देवाश्च सर्वे प्रतिदेवतासु ।\nकर्माणि विज्ञानमयश्च आत्मा परेऽव्यये सर्वे एकीभवन्ति ॥ ७॥", tamil_trans: "கதா: கலா: பஞ்சதஶ ப்ரதிஷ்டா தேவாஶ்ச ஸர்வே ப்ரதிதேவதாஸு |\nகர்மாணி விக்ஞானமயஶ்ச ஆத்மா பரே'வ்யயே ஸர்வே ஏகீபவந்தி || 7 ||", english: "The fifteen parts go back to their causes, and all the senses to their presiding deities. The actions and the Atman, which is pure knowledge, all become one in the Supreme Imperishable." },
            { id: "3.2.8", sanskrit: "यथा नद्यः स्यन्दमानाः समुद्रेऽस्तं गच्छन्ति नामरूपे विहाय ।\nतथा विद्वान् नामरूपाद्विमुक्तः परात्परं पुरुषमुपैति दिव्यम् ॥ ८॥", tamil_trans: "யதா நத்ய: ஸ்யந்தமானா: ஸமுத்ரே'ஸ்தம் கச்சந்தி நாமரூபே விஹாய |\nததா வித்வான் நாமரூபாத் விமுக்த: பராத் பரம் புருஷம் உபைதி திவ்யம் || 8 ||", english: "As flowing rivers disappear into the sea, losing their names and forms, so a wise man, freed from name and form, attains the Purusha, who is greater than the Great." },
            { id: "3.2.9", sanskrit: "स यो ह वै तत्परमं ब्रह्म वेद ब्रह्मैव भवति नास्याब्रह्मवित्कुले भवति ।\nतरति शोकं तरति पाप्मानं गुहाग्रन्थिभ्यो विमुक्तोऽमृतो भवति ॥ ९॥", tamil_trans: "ஸ யோ ஹ வை தத் பரமம் ப்ரஹ்ம வேத ப்ரஹ்மைவ பவதி நாஸ்யா ப்ரஹ்மவித் குலே பவதி |\nதரதி ஶோகம் தரதி பாப்மானம் குஹாக்ரந்திப்யோ விமுக்தோ'ம்ருதோ பவதி || 9 ||", english: "He who knows the Supreme Brahman positively becomes Brahman. In his line is not born one who does not know Brahman. He overcomes grief, he overcomes evil; free from the fetters of the heart, he becomes immortal." },
            { id: "3.2.10", sanskrit: "तदेतदृचाऽभ्युक्तम् । क्रियावन्तः श्रोत्रिया ब्रह्मनिष्ठाः स्वयं जुह्वत एकर्षिं श्रद्धयन्तः ।\nतेषामेवैतां ब्रह्मविद्यां वदेत शिरोव्रतं विधिवद्यैस्तु चीर्णम् ॥ १०॥", tamil_trans: "ததேதத் ருசா'ப்யுக்தம் | க்ரியாவந்த: ஶ்ரோத்ரியா ப்ரஹ்மநிஷ்டா: ஸ்வயம் ஜுஹ்வத ஏகர்ஷிம் ஶ்ரத்தயந்த: |\nதேஷாமேவைதாம் ப்ரஹ்மவித்யாம் வதேத ஶிரோவ்ரதம் விதிவத் யைஸ்து சீர்ணம் || 10 ||", english: "A Rik-verse declares: This Knowledge of Brahman should he told to those only who have performed the necessary duties, who are versed in the Vedas and devoted to Brahman and who, full of faith, have offered oblations in the Ekarshi Fire and performed, according to rule, the rite of carrying fire on the head." },
            { id: "3.2.11", sanskrit: "तदेतत्सत्यमृषिरङ्गिराः पुरोवाच नैतदचीर्णव्रतोऽधीते ।\nनमः परमऋषिभ्यो नमः परमऋषिभ्यः ॥ ११॥", tamil_trans: "ததேதத் ஸத்யம் ருஷிரங்கிரா: புரோவாச நைதத் அசீர்ணவ்ரதோ'தீதே |\nநம: பரம ருஷிப்யோ நம: பரம ருஷிப்ய: || 11 ||", english: "Thus the seer Angiras declared this truth in olden times. A man who has not performed the vow should not read it. Salutation to the great seers! Salutation to the great seers!" }
        ]
    },
    { id: "brihadaranyaka", title: "Brihadaranyaka Upanishad", subtitle: "Great Forest", shanti_mantra: { sanskrit: "ॐ पूर्णमदः...", tamil_trans: "ஓம் பூர்ணமத:...", english: "Om..." }, verses: [{ id: 1, sanskrit: "अहं ब्रह्मास्मि", tamil_trans: "அஹம் பிரம்மாஸ்மி", english: "I am Brahman.", commentary_tamil: "நானே பிரம்மம்.", commentary_english: "I am Brahman." }] }
];

const panchaSuktams = [
    {
        id: "purusha",
        title: "Purusha Suktam (புருஷ சூக்தம்)",
        subtitle: "Hymn of the Cosmic Being",
        verses: [
            { id: 1, sanskrit: "सहस्रशीर्षा पुरुषः सहस्राक्षः सहस्रपात् ।\nस भूमिं विश्वतो वृत्वात्यतिष्ठद्दशाङुलम् ॥ १॥", tamil_trans: "ஸஹஸ்ரஷீர்ஷா புருஷ: ஸஹஸ்ராக்ஷ: ஸஹஸ்ரபாத் |\nஸ பூமிம் விஶ்வதோ வ்ருத்வாத்யதிஷ்டத்தஶாங்குலம் || 1 ||", english: "The Purusha (Cosmic Being) has a thousand heads, a thousand eyes, and a thousand feet. He encompasses the Earth on all sides and extends beyond it by ten fingers." },
            { id: 2, sanskrit: "पुरुष एवेदं सर्वं यद्भूतं यच्च भव्यम् ।\nउतामृतत्वस्येशानो यदन्नेनातिरोहति ॥ २॥", tamil_trans: "புருஷ ஏவேதம் ஸர்வம் யத்பூதம் யச்ச பவ்யம் |\nஉதாம்ருதத்வஸ்யேஶானோ யதன்னேனாதி ரோஹதி || 2 ||", english: "All this is Purusha alone - whatever was and whatever will be. He is also the Lord of Immortality." },
            { id: 3, sanskrit: "एतावानस्य महिमातो ज्यायाँश्च पूरुषः ।\nपादोऽस्य विश्वा भूतानि त्रिपादस्यामृतं दिवि ॥ ३॥", tamil_trans: "ஏதாவானஸ்ய மஹிமாதோ ஜ்யாயாம்ஶ்ச பூருஷ: |\nபாதோ'ஸ்ய விஶ்வா பூதானி த்ரிபாதஸ்யாம்ருதம் திவி || 3 ||", english: "Such is His magnificence, but the Purusha is greater than this. All beings are but a quarter of Him; three-quarters of Him are the immortal in Heaven." },
            { id: 17, sanskrit: "वेदाहमेतं पुरुषं महान्तं आदित्यवर्णं तमसः परस्तात् ।\nतमेवम् विद्वान् अमृत इह भवति नान्यः पन्था विद्यतेऽयनाय ॥", tamil_trans: "வேதாஹமேதம் புருஷம் மஹாந்தம் ஆதித்யவர்ணம் தமஸ: பரஸ்தாத் |\nதமேவம் வித்வான் அம்ருத இஹ பவதி நான்ய: பந்தா வித்யதே'யனாய ||", english: "I know that great Purusha, radiant as the sun, beyond darkness. Knowing Him thus, one becomes immortal here; there is no other path." }
        ]
    },
    {
        id: "narayana",
        title: "Narayana Suktam (நாராயண சூக்தம்)",
        subtitle: "Hymn to Lord Narayana",
        verses: [
            { id: 1, sanskrit: "सहस्रशीर्षं देवं विश्वाक्षं विश्वशम्भुवम् । विश्वं नारायणं देवमक्षरं परमं पदम् ॥", tamil_trans: "ஸஹஸ்ரஷீர்ஷம் தேவம் விஶ்வாக்ஷம் விஶ்வஶம்புவம் | விஶ்வம் நாராயணம் தேவமக்ஷரம் பரமம் பதம் ||", english: "The God with a thousand heads, with eyes everywhere, the source of well-being for the universe. The universe itself is Narayana, the imperishable Supreme Abode." },
            { id: 6, sanskrit: "अनन्तमव्ययं कविगँ समुद्रेऽन्तं विश्वशम्भुवम् । पद्मकोशप्रतीकाशं हृदयं चाप्यधोमुखम् ॥", tamil_trans: "அனந்தமவ்யயம் கவிகம் ஸமுத்ரே'ந்தம் விஶ்வஶம்புவம் | பத்மகோஶப்ரதீகாஶம் ஹ்ருதயம் சாப்யதோமுகம் ||", english: "He is infinite and immutable, the Seer, the source of universal joy. The heart resembles an inverted lotus bud." },
            { id: 13, sanskrit: "ऋतग्ं सत्यं परं ब्रह्म पुरुषं कृष्णपिङ्गलम् । ऊर्ध्वरेतं विरूपाक्षं विश्वरूपाय वै नमो नमः ॥", tamil_trans: "ருதம் ஸத்யம் பரம் ப்ரம்ம புருஷம் க்ருஷ்ணபிங்கலம் | ஊர்த்வரேதம் விரூபாக்ஷம் விஶ்வரூபாய வை நமோ நம: ||", english: "Salutations to the Universal Form, the Truth, the Supreme Brahman, the Purusha of dark-tawny hue, with upturned creative energy and diverse eyes." }
        ]
    },
    {
        id: "sri",
        title: "Sri Suktam (ஸ்ரீ சூக்தம்)",
        subtitle: "Hymn to Goddess Lakshmi",
        verses: [
            { id: 1, sanskrit: "हिरण्यवर्णां हरिणीं सुवर्णरजतस्रजाम् । चन्द्रां हिरण्मयीं लक्ष्मीं जातवेदो म आवह ॥ १॥", tamil_trans: "ஹிரண்யவர்ணாம் ஹரிணீம் ஸுவர்ணராஜதஸ்ரஜாம் | சந்த்ராம் ஹிரண்மயீம் லக்ஷ்மீம் ஜாதவேதோ ம ஆவஹ || 1 ||", english: "invoke for me, O Agni, that Goddess Lakshmi, of golden color, of the hue of a gazelle, wearing garlands of gold and silver..." },
            { id: 3, sanskrit: "अश्वपूर्वां रथमध्यां हस्तिनादप्रबोधिनीम् । श्रियं देवीमुपह्वये श्रीर्मा देवी जुषताम् ॥ ३॥", tamil_trans: "அஶ்வபூர்வாம் ரதமத்யாம் ஹஸ்தினாதப்ரபோதினீம் | ஶ்ரியம் தேவிமுபஹ்வயே ஶ்ரீர்மா தேவி ஜுஷதாம் || 3 ||", english: "Invoke the Goddess Sri, preceded by horses, seated in a chariot, awakened by the trumpet of elephants." }
        ]
    },
    {
        id: "durga",
        title: "Durga Suktam (துர்கா சூக்தம்)",
        subtitle: "Hymn to Goddess Durga",
        verses: [
            { id: 1, sanskrit: "जातो वेदसे सुनवाम सोम मरातीयतो निदहाति वेदः ।\nस नः पर्षदति दुर्गाणि विश्वा नावेव सिन्धुं दुरितात्यग्निः ॥ १॥", tamil_trans: "ஜாதவேதஸே ஸுனவாம ஸோம மராதாயதோ நிதஹாதி வேத: |\nஸ ந: பர்ஷததி துர்காணி விஶ்வா நாவேவ ஸிந்தும் துரிதாத்யக்னி: || 1 ||", english: "We press Soma for the Knower of all beings (Agni/Durga). May He burn away the wealth of our enemies. May Agni carry us through all difficulties as a boat carries one across a river." },
            { id: 2, sanskrit: "तामग्निवर्णां तपसा ज्वलन्तीं वैरोचनीं कर्मफलेषु जुष्टाम् ।\nदुर्गां देवीग्ं शरणमहं प्रपद्ये सुतरसि तरसे नमः ॥ २॥", tamil_trans: "தாமக்னிவர்ணாம் தபஸா ஜ்வலந்தீம் வைரோசனீம் கர்மபலேஷு ஜுஷ்டாம் |\nதுர்காம் தேவிம் ஶரணமஹம் ப்ரபத்யே ஸுதரஸி தரஸே நம: || 2 ||", english: "I take refuge in Goddess Durga, who shines like fire, radiant with tapas, belonging to the Supreme, sought for the fruit of actions. Salutations to the Deliverer." }
        ]
    },
    {
        id: "bhu",
        title: "Bhu Suktam (பூ சூக்தம்)",
        subtitle: "Hymn to Mother Earth",
        verses: [
            { id: 1, sanskrit: "भूमिर्बुम्ना द्यौर्वरिणा अन्तरिक्षं महित्वा ।", tamil_trans: "பூமிர்பும்னா த்யௌர்வரிணா அந்தரிக்ஷம் மஹித்வா |", english: "The Earth is great by its vastness, the Heavens by their expanse, the atmosphere by its greatness." },
            { id: 13, sanskrit: "विष्णुपत्नीं महीम् देवीं माधवीं माधवप्रियाम् । लक्ष्मीं प्रियसखीं देवीं नमाम्यच्युतवल्लभाम् ॥", tamil_trans: "விஷ்ணுபத்னீம் மஹீம் தேவிம் மாதவிம் மாதவப்ரியாம் | லக்ஷ்மீம் ப்ரியஸகீம் தேவிம் நமாம்யச்யுதவல்லபாம் ||", english: "I bow to the Consort of Vishnu, the Great Goddess Earth, Madhavi (Spring), beloved of Madhava, Lakshmi, and the beloved of Achyuta." }
        ]
    }
];

